					}
					flagBoolValues[spec.name] = true
					flagSet[spec.name] = true
				}
				i++
			} else {
				// String flag requires value
				var val string
				if valuePart != nil {
					// Value provided after =
					val = *valuePart
					// Even if empty string, it's considered set (for include-selector empty case)
					flagValues[spec.name] = val
					flagSet[spec.name] = true
					i++
				} else {
					// Need next arg
					if i+1 >= len(args) {
						// Missing arg
						printError("error: flag needs an argument: -%s", spec.name)
						os.Exit(1)
					}
					next := args[i+1]
					if strings.HasPrefix(next, "-") {
						// Next is another flag, so missing arg
						printError("error: flag needs an argument: -%s", spec.name)
						os.Exit(1)
					}
					val = next
					flagValues[spec.name] = val
					flagSet[spec.name] = true
					i += 2
				}
			}
		} else {
			// Positional arg
			positional = append(positional, arg)
			i++
		}
	}

	// Check unknown positional args
	if len(positional) > 0 {
		// error: unknown arguments: <joined>
		// Note format: if multiple, joined by space
		joined := strings.Join(positional, " ")
		// This error also shows help hint
		fmt.Fprintf(os.Stderr, "\nerror: unknown arguments: %s\n\nHere is how you can use the CLI:\n\n    echo \"<strong>important</strong>\" | html2markdown\n\n", joined)
		os.Exit(1)
	}

	// Now validate selectors early (before checking stdin)
	// include-selector and exclude-selector
	if flagSet["include-selector"] {
		v := flagValues["include-selector"]
		if err := validateSelector(v); err != nil {
			// error: invalid value "<v>" for flag -include-selector: <err>
			// Need to preserve original value representation with quotes
			// For empty string, error shows "" as empty quotes
			printError("error: invalid value \"%s\" for flag -include-selector: %s", v, err.Error())
			os.Exit(1)
		}
	}
	if flagSet["exclude-selector"] {
		v := flagValues["exclude-selector"]
		if err := validateSelector(v); err != nil {
			printError("error: invalid value \"%s\" for flag -exclude-selector: %s", v, err.Error())
			os.Exit(1)
		}
	}

	// Validate table opts requiring plugin-table
	// List of table opt flags
	tableOptFlags := []string{
		"opt-table-cell-padding-behavior",
		"opt-table-header-promotion",
		"opt-table-newline-behavior",
		"opt-table-presentation-tables",
		"opt-table-skip-empty-rows",
		"opt-table-span-cell-behavior",
	}
	// If any of these set and plugin-table not set, error
	if !flagSet["plugin-table"] || !flagBoolValues["plugin-table"] {
		for _, f := range tableOptFlags {
			if flagSet[f] {
				printError("error: --%s requires --plugin-table to be enabled", f)
				os.Exit(1)
			}
		}
	}

	// Validate bool flags for table opts already done (parseBool). For bool flags without value, they are true, so already validated.

	// Validate opt-strong-delimiter early? But original validates it only when stdin present? For strong delimiter, validation should happen even without stdin? Actually earlier we saw:
	// --opt-strong-delimiter="***" without stdin gave piped error, not invalid value. So validation of strong delimiter happens AFTER stdin check. Similarly table plugin init invalid value without stdin gave piped error.
	// But bool parse errors and requires plugin check happen BEFORE stdin check (they gave their own error even without stdin).
	// So order:
	// 1. Unknown flags, missing args, selector validation, requires plugin, bool parse errors => before stdin check
	// 2. Strong delimiter validation, table plugin init validation => after stdin check? Actually after checking if input is provided via file, if input via file exists, then we don't need stdin. So stdin check only when --input not set.
	// Let's do:
	// - If --input set, skip stdin check
	// - Else, check if stdin is char device: if char device, error piped
	// - Then validate strong delimiter and table plugin options

	// Check input flag handling
	var inputFiles []string
	var inputPattern string
	if flagSet["input"] {
		inputPattern = flagValues["input"]
		// Determine if pattern contains glob meta
		// For simplicity, check for *, ?, [, ], {, } 
		hasGlob := strings.ContainsAny(inputPattern, "*?[]{}")
		if hasGlob {
			matches, err := filepath.Glob(inputPattern)
			if err != nil {
				// If glob pattern invalid, treat as no files?
				// Original would give "no files found"
				fmt.Fprintf(os.Stderr, "\nerror: no files found matching pattern \"%s\"\n\nHere is how you can use a glob to match multiple files:\n\n    html2markdown --input \"src/*.html\" --output \"dist/\"\n\n", inputPattern)
				os.Exit(1)
			}
			// Filter to files only
			var filtered []string
			for _, m := range matches {
				info, err := os.Stat(m)
				if err != nil {
					continue
				}
				if info.Mode().IsRegular() {
					filtered = append(filtered, m)
				}
			}
			if len(filtered) == 0 {
				fmt.Fprintf(os.Stderr, "\nerror: no files found matching pattern \"%s\"\n\nHere is how you can use a glob to match multiple files:\n\n    html2markdown --input \"src/*.html\" --output \"dist/\"\n\n", inputPattern)
				os.Exit(1)
			}
			inputFiles = filtered
		} else {
			// No glob meta
			info, err := os.Stat(inputPattern)
			if err != nil {
				fmt.Fprintf(os.Stderr, "\nerror: no files found matching pattern \"%s\"\n\nHere is how you can use a glob to match multiple files:\n\n    html2markdown --input \"src/*.html\" --output \"dist/\"\n\n", inputPattern)
				os.Exit(1)
			}
			if info.IsDir() {
				fmt.Fprintf(os.Stderr, "\nerror: input path \"%s\" is a directory, not a file\n\nHere is how you can use a glob to match multiple files:\n\n    html2markdown --input \"src/*.html\" --output \"dist/\"\n\n", inputPattern)
				os.Exit(1)
			}
			if !info.Mode().IsRegular() {
				// Treat as not found?
				fmt.Fprintf(os.Stderr, "\nerror: no files found matching pattern \"%s\"\n\nHere is how you can use a glob to match multiple files:\n\n    html2markdown --input \"src/*.html\" --output \"dist/\"\n\n", inputPattern)
				os.Exit(1)
			}
			inputFiles = []string{inputPattern}
		}
		// Sort input files for deterministic order
		sort.Strings(inputFiles)
	} else {
		// No input flag: need stdin
		// Check if stdin is char device
		st, err := os.Stdin.Stat()
		if err != nil {
			// Assume not piped?
			fmt.Fprintf(os.Stderr, "\nerror: the html input should be piped into the cli\n\nHere is how you can use the CLI:\n\n    echo \"<strong>important</strong>\" | html2markdown\n\n")
			os.Exit(1)
		}
		if (st.Mode() & os.ModeCharDevice) != 0 {
			fmt.Fprintf(os.Stderr, "\nerror: the html input should be piped into the cli\n\nHere is how you can use the CLI:\n\n    echo \"<strong>important</strong>\" | html2markdown\n\n")
			os.Exit(1)
		}
	}

	// Now validate strong delimiter
	strongDelim := "**"
	if flagSet["opt-strong-delimiter"] {
		strongDelim = flagValues["opt-strong-delimiter"]
		if strongDelim != "**" && strongDelim != "__" {
			// Error format: error: invalid value for --opt-strong-delimiter="***" must be exactly 2 characters of "**" or "__"
			// Note: need to show the value as provided, with quotes? Original shows "***" inside double quotes, with the flag including = and quoted value? 
			// For --opt-strong-delimiter="***" (with = and maybe quotes), the original error shows --opt-strong-delimiter="***"
			// If provided as --opt-strong-delimiter *** (space), it would show --opt-strong-delimiter="***" as well? Let's test original: echo "<p>hi</p>" | ./executable --opt-strong-delimiter "***" 2>&1 -> should show same?
			// We tested earlier with --opt-strong-delimiter="***" and it showed that form. We need to replicate same form: flag name with = and value in double quotes, with value itself as provided (including any quotes? but value is ***).
			// So we will always show as --opt-strong-delimiter="<value>"
			printError("error: invalid value for --opt-strong-delimiter=\"%s\" must be exactly 2 characters of \"**\" or \"__\"", strongDelim)
			os.Exit(1)
		}
	}

	// Validate table plugin options (after stdin check)
	if flagSet["plugin-table"] && flagBoolValues["plugin-table"] {
		// cell padding behavior
		if flagSet["opt-table-cell-padding-behavior"] {
			v := flagValues["opt-table-cell-padding-behavior"]
			if v != "aligned" && v != "minimal" && v != "none" {
				printError("error: error while initializing \"table\" plugin: unknown value \"%s\" for cell padding behavior", v)
				os.Exit(1)
			}
		}
		if flagSet["opt-table-span-cell-behavior"] {
			v := flagValues["opt-table-span-cell-behavior"]
			if v != "empty" && v != "mirror" {
				printError("error: error while initializing \"table\" plugin: unknown value \"%s\" for span cell behavior", v)
				os.Exit(1)
			}
		}
		if flagSet["opt-table-newline-behavior"] {
			v := flagValues["opt-table-newline-behavior"]
			if v != "skip" && v != "preserve" {
				printError("error: error while initializing \"table\" plugin: unknown value \"%s\" for newline behavior", v)
				os.Exit(1)
			}
		}
		// bool flags already validated
	}

	// Now conversion setup
	// Options
	domain := ""
	if flagSet["domain"] {
		domain = flagValues["domain"]
	}
	includeSelector := ""
	if flagSet["include-selector"] {
		includeSelector = flagValues["include-selector"]
	}
	excludeSelector := ""
	if flagSet["exclude-selector"] {
		excludeSelector = flagValues["exclude-selector"]
	}
	// Table options defaults
	cellPadding := "aligned"
	if flagSet["opt-table-cell-padding-behavior"] {
		cellPadding = flagValues["opt-table-cell-padding-behavior"]
	}
	headerPromotion := false
	if flagSet["opt-table-header-promotion"] {
		headerPromotion = flagBoolValues["opt-table-header-promotion"]
		// If flag set without value, we already set true. If set with value, bool value.
		// But also need to handle case where flag appears without value explicitly: we treat as true.
	}
	newlineBehavior := "skip"
	if flagSet["opt-table-newline-behavior"] {
		newlineBehavior = flagValues["opt-table-newline-behavior"]
	}
	presentationTables := false
	if flagSet["opt-table-presentation-tables"] {
		presentationTables = flagBoolValues["opt-table-presentation-tables"]
	}
	skipEmptyRows := false
	if flagSet["opt-table-skip-empty-rows"] {
		skipEmptyRows = flagBoolValues["opt-table-skip-empty-rows"]
	}
	spanBehavior := "empty"
	if flagSet["opt-table-span-cell-behavior"] {
		spanBehavior = flagValues["opt-table-span-cell-behavior"]
	}
	strikethrough := false
	if flagSet["plugin-strikethrough"] {
		strikethrough = flagBoolValues["plugin-strikethrough"]
	}
	tablePlugin := false
	if flagSet["plugin-table"] {
		tablePlugin = flagBoolValues["plugin-table"]
	}

	// Converter
	converter := NewConverter(ConverterOptions{
		StrongDelimiter:      strongDelim,
		Domain:               domain,
		IncludeSelector:      includeSelector,
		ExcludeSelector:      excludeSelector,
		CellPadding:          cellPadding,
		HeaderPromotion:      headerPromotion,
		NewlineBehavior:      newlineBehavior,
		PresentationTables:   presentationTables,
		SkipEmptyRows:        skipEmptyRows,
		SpanBehavior:         spanBehavior,
		Strikethrough:        strikethrough,
		TablePlugin:          tablePlugin,
	})

	// Handle input files vs stdin
	var outputs []FileOutput // to hold results for file output

	if len(inputFiles) > 0 {
		// Read each file and convert
		for _, fpath := range inputFiles {
			data, err := os.ReadFile(fpath)
			if err != nil {
				// Should not happen, but if file not readable, treat as error?
				fmt.Fprintf(os.Stderr, "error reading file %s: %v\n", fpath, err)
				os.Exit(1)
			}
			md := converter.Convert(string(data))
			outputs = append(outputs, FileOutput{InputPath: fpath, Content: md})
		}

		// Output handling
		outputPath := ""
		if flagSet["output"] {
			outputPath = flagValues["output"]
		}
		outputOverwrite := false
		if flagSet["output-overwrite"] {
			outputOverwrite = flagBoolValues["output-overwrite"]
		}

		// If single file and no output specified, print to stdout
		if len(inputFiles) == 1 && outputPath == "" {
			fmt.Print(outputs[0].Content)
			os.Exit(0)
		}

		// If multiple files and no output, error
		if len(inputFiles) > 1 && outputPath == "" {
			fmt.Fprintf(os.Stderr, "\nerror: when processing multiple input files --output needs to be a directory\n\nHere is how you can use a glob to match multiple files:\n\n    html2markdown --input \"src/*.html\" --output \"dist/\"\n\n")
			os.Exit(1)
		}

		// Now handle output path
		if outputPath == "" {
			// Should not happen for multiple? For single, we already handled stdout case. But if single and output not set, we already printed.
			// For multiple with output set, we proceed
			// Actually for single with no output, we printed, so this branch not needed
			fmt.Print(outputs[0].Content)
			os.Exit(0)
		}

		// Determine if output path ends with "/"
		isDirOutput := strings.HasSuffix(outputPath, "/")

		// For multiple files, output must be dir (must end with "/")
		if len(inputFiles) > 1 && !isDirOutput {
			// error: when processing multiple input files, --output "out.md" must end with "out.md/" to indicate a directory
			// Note: the output path in message is the basename? In our earlier tests, for /tmp/out.md it showed "out.md", not full path? Let's check:
			// We saw error for "/tmp/out.md" showed "out.md" (basename). For "/tmp/Aout" showed "Aout". So it shows basename of output path, not full path.
			base := filepath.Base(outputPath)
			// But if outputPath ends without slash, base is file name. If outputPath is "/tmp/out.md", base is "out.md"
			fmt.Fprintf(os.Stderr, "\nerror: when processing multiple input files, --output \"%s\" must end with \"%s/\" to indicate a directory\n\n", base, base)
			os.Exit(1)
		}

		if isDirOutput {
			// Output is directory
			// Check if path exists and is file -> mkdir error
			info, err := os.Stat(outputPath)
			if err == nil {
				if !info.IsDir() {
					// exists and is file
					fmt.Fprintf(os.Stderr, "\nerror: mkdir %s: file exists\n\n", outputPath)
					os.Exit(1)
				}
				// exists and is dir
				// For single file case, we need to check if target file exists inside
				// For multiple files, check if any target exists or if dir contains files that would be overwritten?
				// According to our earlier analysis, for dir output, we should check if any target file already exists and overwrite false => error output path already exists (showing dir path)
				// But also for multiple files, if dir exists and is empty, we should allow (no target exists yet). However our earlier analysis also showed that for multiple files, if dir exists and contains any file that is target, error. If dir exists empty, allow.
				// For single file case, if dir exists empty, allow, but if target file exists, error.
				// Implementation: compute target file paths and check existence
				// If any exists and !overwrite, error
				// Also need to consider case where dir exists but is not empty with unrelated files: we allowed earlier for multiple files? We saw for multiple files, dir exists with unrelated file allowed (status 0). So we should only check if target files exist, not if dir exists at all.
				// Wait earlier we had case: multiple files, dir exists with unrelated file -> allowed (status 0). So we should NOT error if dir exists with unrelated files, only if target files overlap.
				// But earlier we also had case: multiple files, dir exists empty -> allowed. So same logic: only check target overlap.
				// However, we also had case: multiple files, dir exists with one of the target files (a.md exists) -> error. That matches target overlap check.
				// For single file case: dir exists with target file (a.md) -> error (as observed)
				// For single file case: dir exists with different file (b.md when target is a.md) -> allowed (as observed)
				// So for dir output, error only if target file exists and no overwrite.

				// But what about case where dir exists and is not empty but target files don't overlap? We allowed. So implement that.

				// Check target existence
				targets := computeTargets(inputFiles, outputPath)
				for _, t := range targets {
					if _, err := os.Stat(t); err == nil {
						if !outputOverwrite {
							// error: output path "<outputPath>" already exists
							// Note: outputPath shown as provided (full path if absolute)
							fmt.Fprintf(os.Stderr, "\nerror: output path \"%s\" already exists. Use --output-overwrite to replace existing files\n\n", outputPath)
							os.Exit(1)
						}
					}
				}
				// If overwrite false and no target exists, proceed (even though dir exists)
				// If overwrite true, proceed regardless
			} else {
				// Dir does not exist, create it (mkdir -p)
				// Need to create parent dirs
				err := os.MkdirAll(outputPath, 0755)
				if err != nil {
					fmt.Fprintf(os.Stderr, "\nerror: %v\n\n", err)
					os.Exit(1)
				}
			}

			// Now compute targets again and write
			targets := computeTargets(inputFiles, outputPath)
			// Ensure dir exists (if just created, it's there; if existed, it's there)
			os.MkdirAll(outputPath, 0755)
			for i, tpath := range targets {
				// Write file
				// Ensure parent dir for tpath exists (should be outputPath itself, but just in case)
				dir := filepath.Dir(tpath)
				os.MkdirAll(dir, 0755)
				err := os.WriteFile(tpath, []byte(outputs[i].Content), 0644)
				if err != nil {
					fmt.Fprintf(os.Stderr, "error writing file %s: %v\n", tpath, err)
					os.Exit(1)
				}
			}
			os.Exit(0)
		} else {
			// Output is file (no trailing slash), single file case
			// Check if output path exists
			info, err := os.Stat(outputPath)
			if err == nil {
				if info.IsDir() {
					// Path exists and is dir, but without slash => error path "<basename>" exists and is a directory, did you mean "<basename>/"?
					base := filepath.Base(outputPath)
					fmt.Fprintf(os.Stderr, "\nerror: path \"%s\" exists and is a directory, did you mean \"%s/\"?\n\nThe --output must end with \"/\" to indicate a directory\n\n", base, base)
					os.Exit(1)
				}
				// Exists and is file
				if !outputOverwrite {
					fmt.Fprintf(os.Stderr, "\nerror: output path \"%s\" already exists. Use --output-overwrite to replace existing files\n\n", outputPath)
					os.Exit(1)
				}
			}
			// Ensure parent dirs exist
			parent := filepath.Dir(outputPath)
			if parent != "." && parent != "" {
				os.MkdirAll(parent, 0755)
			}
			err = os.WriteFile(outputPath, []byte(outputs[0].Content), 0644)
			if err != nil {
				fmt.Fprintf(os.Stderr, "error writing file %s: %v\n", outputPath, err)
				os.Exit(1)
			}
			os.Exit(0)
		}

	} else {
		// No input files, read stdin
		data, err := io.ReadAll(os.Stdin)
		if err != nil {
			fmt.Fprintf(os.Stderr, "error reading stdin: %v\n", err)
			os.Exit(1)
		}
		htmlContent := string(data)
		md := converter.Convert(htmlContent)

		outputPath := ""
		if flagSet["output"] {
			outputPath = flagValues["output"]
		}
		outputOverwrite := false
		if flagSet["output-overwrite"] {
			outputOverwrite = flagBoolValues["output-overwrite"]
		}

		if outputPath == "" {
			fmt.Print(md)
			os.Exit(0)
		}

		isDirOutput := strings.HasSuffix(outputPath, "/")
		if isDirOutput {
			// Output to dir from stdin? What should happen?
			// The original tool: when stdin is used and output is dir with slash, what does it do? It probably errors? Let's think: input is stdin (single), output dir with slash would need a filename? But we have no input filename. Maybe it errors? Let's test original behavior for stdin + output dir.
			// We haven't tested. Let's test quickly: echo "<p>hi</p>" | ./executable --output /tmp/outdir/ 2>&1
			// We can test later, but for now assume it should create file with default name? Or error? Safer to treat as file output dir: since input is stdin (no filename), we cannot determine output filename, so maybe it should error?
			// Let's test original in this environment if possible, but we are inside Go build script, not easy. We'll handle: if stdin and output dir with slash, we should error? Or create file named "index.md" or something?
			// For simplicity, if output ends with "/", we will write to outputPath + "index.md" or just error? Let's check original's behavior for stdin + output dir.
			// We'll later test original manually, but for now, if output is dir, we will consider error: output path is directory? Actually we could treat as file creation with name "index.md" or just write to dir? Let's attempt to mimic: if stdin and output dir, the tool might write to output dir as file? Unclear.
			// For now, handle as: if output ends with "/", create dir and write file named "index.md" inside? Or we could error "output path ... is a directory"?
			// Let's search mental: original tool examples show --input file.html --output file.md, and --input "src/*.html" --output "dist/". For stdin case, they show piping to stdout, not to dir. So output dir with stdin may not be supported and may error. We will implement: if output ends with "/", error "output path ... already exists"? Not.
			// Simpler: treat output path as file regardless of trailing slash for stdin? If ends with "/", we will create file inside with name "index.md" or just write to stdout? Let's leave for now: if output ends with "/", we will create dir and write file named "stdin.md"? Could be "index.md".
			// To avoid complexity, we will handle: if output ends with "/", we treat as dir and create file named "out.md"? But spec says if --input is directory or glob, --output must be directory. For stdin, input is not directory, so output can be file OR directory? Let's test original later.
			// For now, if output ends with "/", we will check if it's file, error mkdir, else create dir and write file with name "index.md" ??? Might cause test failure if not matched, but we can adjust later.

			// Let's implement: for stdin, if output ends with "/", we will create dir and write file named "index.md" ??? Actually let's test original behavior quickly via external script after building.

			// For now, just handle as file: if output is dir, create dir and write to outputPath + "index.md"
			info, err := os.Stat(outputPath)
			if err == nil && !info.IsDir() {
				fmt.Fprintf(os.Stderr, "\nerror: mkdir %s: file exists\n\n", outputPath)
				os.Exit(1)
			}
			os.MkdirAll(outputPath, 0755)
			// Check target existence
			target := filepath.Join(outputPath, "index.md")
			// Actually maybe it should be output path itself? Let's use index.md
			if _, err := os.Stat(target); err == nil && !outputOverwrite {
				fmt.Fprintf(os.Stderr, "\nerror: output path \"%s\" already exists. Use --output-overwrite to replace existing files\n\n", outputPath)
				os.Exit(1)
			}
			os.WriteFile(target, []byte(md), 0644)
			os.Exit(0)
		} else {
			// Output file
			info, err := os.Stat(outputPath)
			if err == nil {
				if info.IsDir() {
					base := filepath.Base(outputPath)
					fmt.Fprintf(os.Stderr, "\nerror: path \"%s\" exists and is a directory, did you mean \"%s/\"?\n\nThe --output must end with \"/\" to indicate a directory\n\n", base, base)
					os.Exit(1)
				}
				if !outputOverwrite {
					fmt.Fprintf(os.Stderr, "\nerror: output path \"%s\" already exists. Use --output-overwrite to replace existing files\n\n", outputPath)
					os.Exit(1)
				}
			}
			parent := filepath.Dir(outputPath)
			if parent != "." && parent != "" {
				os.MkdirAll(parent, 0755)
			}
			os.WriteFile(outputPath, []byte(md), 0644)
			os.Exit(0)
		}
	}
}

func parseBool(s string) (bool, error) {
	// Use strconv.ParseBool which handles 1, t, T, TRUE, true, True, 0, f, F, FALSE, false, False
	return strconv.ParseBool(s)
}

func validateSelector(s string) error {
