func isListBlock(s string) bool {
	// Check if block starts with "- " or "* " or "+ " or ordered like "1. "
	// Also after trimming leading spaces?
	lines := strings.Split(s, "\n")
	if len(lines) == 0 {
		return false
	}
	first := strings.TrimSpace(lines[0])
	if strings.HasPrefix(first, "- ") || strings.HasPrefix(first, "* ") || strings.HasPrefix(first, "+ ") {
		return true
	}
	// Ordered list: e.g., "1. ", "2. ", "10. "
	re := regexp.MustCompile(`^\d+\.\s`)
	return re.MatchString(first)
}

func filterTopMost(nodes []*html.Node) []*html.Node {
	// Keep only nodes that are not descendant of another node in list
	var filtered []*html.Node
	for _, n := range nodes {
		isDescendant := false
		for _, other := range nodes {
			if n == other {
				continue
			}
			// Check if n is descendant of other
			for p := n.Parent; p != nil; p = p.Parent {
				if p == other {
					isDescendant = true
					break
				}
			}
			if isDescendant {
				break
			}
		}
		if !isDescendant {
			filtered = append(filtered, n)
		}
	}
	// Sort by document order? For simplicity, keep order as found, but need to sort by position
	// We'll sort by depth-first order? Our find function already does depth-first, so filtered should be in order
	return filtered
}

func findBody(n *html.Node) *html.Node {
	if n.Type == html.ElementNode && n.Data == "body" {
		return n
	}
	for c := n.FirstChild; c != nil; c = c.NextSibling {
		if res := findBody(c); res != nil {
			return res
		}
	}
	return nil
}

func matchesSelector(node *html.Node, selector string) bool {
	if node.Type != html.ElementNode {
		return false
	}
	// Support comma separated
	parts := strings.Split(selector, ",")
	for _, part := range parts {
		part = strings.TrimSpace(part)
		if part == "" {
			continue
		}
		if matchesSingleSelector(node, part) {
			return true
		}
	}
	return false
}

func matchesSingleSelector(node *html.Node, sel string) bool {
