		tokens := strings.Fields(sel)
		// Last token must match current node
		last := tokens[len(tokens)-1]
		if !matchesSimpleToken(node, last) {
			return false
		}
		// For preceding tokens, need to find ancestors matching
		// We will walk up ancestors and try to match tokens in reverse order
		// This is simplified: require each preceding token to match some ancestor in order
		anc := node.Parent
		idx := len(tokens) - 2
		for anc != nil && idx >= 0 {
			if matchesSimpleToken(anc, tokens[idx]) {
				idx--
			}
			anc = anc.Parent
		}
		return idx < 0
	}

