func matchesSimpleToken(node *html.Node, token string) bool {
	if token == "*" {
		return true
	}
	// Token may be like "div", ".a", "#id", "div.a", "div#id", "div.a#b", ".a#b", etc
	// Parse tag, classes, id

	// Extract tag, id, classes
	// Find id
	var tag string
	var id string
	var classes []string

	// Check for #id
	if strings.Contains(token, "#") {
		parts := strings.SplitN(token, "#", 2)
		// parts[0] may contain tag and classes before #
		tagPart := parts[0]
		idAndRest := parts[1]
		// idAndRest may contain "." for classes after id
		if strings.Contains(idAndRest, ".") {
			idParts := strings.SplitN(idAndRest, ".", 2)
			id = idParts[0]
			// classes after
			rest := idParts[1]
			classes = append(classes, strings.Split(rest, ".")...)
		} else {
			id = idAndRest
		}
		// tagPart may contain classes
		if strings.Contains(tagPart, ".") {
			tp := strings.Split(tagPart, ".")
			if tp[0] != "" {
				tag = tp[0]
			}
			for _, c := range tp[1:] {
				if c != "" {
					classes = append(classes, c)
				}
			}
		} else {
			if tagPart != "" {
				tag = tagPart
			}
		}
	} else {
		// No id, check for classes
		if strings.Contains(token, ".") {
			parts := strings.Split(token, ".")
			if parts[0] != "" {
				tag = parts[0]
			}
			for _, c := range parts[1:] {
				if c != "" {
					classes = append(classes, c)
				}
			}
		} else {
			// Only tag
			tag = token
		}
	}

	// If tag is present and not "*", check
	if tag != "" && tag != "*" {
		if node.Data != tag {
			return false
		}
	}
	// Check id
	if id != "" {
		if getAttr(node, "id") != id {
			return false
		}
	}
	// Check classes
	if len(classes) > 0 {
		classAttr := getAttr(node, "class")
		// classAttr is space-separated list
		nodeClasses := strings.Fields(classAttr)
		classSet := make(map[string]bool)
		for _, c := range nodeClasses {
			classSet[c] = true
		}
		for _, needed := range classes {
			if !classSet[needed] {
				return false
			}
		}
	}
	return true
}

func getAttr(n *html.Node, key string) string {
	for _, a := range n.Attr {
		if a.Key == key {
			return a.Val
		}
	}
	return ""
}

