func (c *Converter) convertChildren(n *html.Node, indent int, inTable bool) string {
	var sb strings.Builder
	var lastWasBr bool
	var brCount int

	// For handling consecutive br's
	// We'll iterate children and handle br specially
	for child := n.FirstChild; child != nil; child = child.NextSibling {
		if child.Type == html.ElementNode && strings.ToLower(child.Data) == "br" {
			// Count consecutive br's (including whitespace text nodes between?)
			// Look ahead to count br's
			// For simplicity, we will collect br sequence
			// If this is start of sequence, count how many br's in a row (ignoring whitespace text nodes)
			if !lastWasBr {
				// Count consecutive br's
				count := 1
				next := child.NextSibling
				for next != nil {
					if next.Type == html.TextNode {
						// If text node is whitespace only, skip
						if strings.TrimSpace(next.Data) == "" {
							next = next.NextSibling
							continue
						} else {
							break
						}
					}
					if next.Type == html.ElementNode && strings.ToLower(next.Data) == "br" {
						count++
						next = next.NextSibling
					} else {
						break
					}
				}
				brCount = count
				if count == 1 {
					sb.WriteString("  \n")
				} else {
					// Two or more br's => blank line
					sb.WriteString("\n\n")
				}
				lastWasBr = true
				// If count >1, we need to skip the next br's that we counted
				// Advance child pointer to after the sequence
				// We have child as current br, we counted count br's including current
				// So we need to skip count-1 next br's
				skip := count - 1
				for skip > 0 && child.NextSibling != nil {
					// Move to next sibling, skipping whitespace text nodes as well
					next := child.NextSibling
					// Skip whitespace text
					for next != nil && next.Type == html.TextNode && strings.TrimSpace(next.Data) == "" {
						next = next.NextSibling
					}
					if next != nil && next.Type == html.ElementNode && strings.ToLower(next.Data) == "br" {
						child = next
						skip--
					} else {
						break
					}
				}
			} else {
				// Already handled as part of previous sequence, skip
				// Reset lastWasBr after sequence?
				// Actually if we are in sequence, we already skipped, so this shouldn't happen
				lastWasBr = false
			}
			continue
		}
		// Non-br node
		lastWasBr = false
		brCount = 0

		if child.Type == html.TextNode {
			// For text, collapse whitespace? Need to handle escaping
			txt := child.Data
			// If parent is pre, keep raw
			if n.Data == "pre" {
				sb.WriteString(txt)
			} else {
				// Normalize whitespace: replace \n, \r, \t with space, collapse multiple spaces into single space? But preserve single spaces
				// For <p> with newlines inside, we want to collapse to space: "<p>\n  hello   world\n  foo\n</p>" => "hello world foo"
				// So we should replace any whitespace sequence (including newline, tab, multiple spaces) with single space, then trim?
				// However for inline, we need to keep spaces between words
				// Let's replace \n and \r with space, then collapse multiple spaces?
				// But also need to handle that text may be just whitespace between blocks, which should be ignored

				// If text is all whitespace, skip? For block handling, we ignore whitespace-only text nodes between elements
				if strings.TrimSpace(txt) == "" {
					// Whitespace-only, check if it's between inline elements? For now, if it contains newline, treat as space? But for block separation we already use "\n\n"
					// We'll skip whitespace-only text if it's not needed
					// However, for inline, a single space between elements is needed
					// For simplicity, if parent is block like p, ul, etc, whitespace-only text can be ignored
					// We'll just add a single space if needed
					continue
				}
				// Normalize: replace newlines and tabs with space
				normalized := strings.ReplaceAll(txt, "\n", " ")
				normalized = strings.ReplaceAll(normalized, "\r", " ")
				normalized = strings.ReplaceAll(normalized, "\t", " ")
				// Collapse multiple spaces into single space
				normalized = regexp.MustCompile(`\s+`).ReplaceAllString(normalized, " ")
				// Now escape markdown
				escaped := escapeText(normalized)
				sb.WriteString(escaped)
			}
		} else if child.Type == html.ElementNode {
			inner := c.convertNode(child, indent, inTable)
			sb.WriteString(inner)
		}
	}
	return sb.String()
}

