func escapeInlineCode(s string) string {
	// Find longest sequence of backticks in s
	max := 0
	count := 0
	for _, ch := range s {
		if ch == '`' {
			count++
			if count > max {
				max = count
			}
		} else {
			count = 0
		}
	}
	// Need fence longer than max
	fenceLen := max + 1
	if fenceLen < 1 {
		fenceLen = 1
	}
	fence := strings.Repeat("`", fenceLen)
	// If s starts or ends with backtick or space, need to add spaces inside fence? Original does something like "`` ` ``" for "`" ?
	// For content "`", they gave "`` ` ``" (with spaces)
	// For content "``", they gave "``` `` ```"
	// So they add spaces if content starts or ends with backtick or space, or contains fence?
	// Implement: if s starts with backtick or space, or ends with backtick or space, add spaces around?
	// Commonmark: to avoid fence merging, add spaces if needed
	needsSpace := false
	if strings.HasPrefix(s, "`") || strings.HasPrefix(s, " ") || strings.HasSuffix(s, "`") || strings.HasSuffix(s, " ") {
		needsSpace = true
	}
	if needsSpace {
		return fence + " " + s + " " + fence
	}
	return fence + s + fence
}

