func resolveURL(base, ref string) string {
	if ref == "" {
		return base
	}
	// If ref is absolute (http://, https://, //, etc), return as is? But for //, urljoin will handle adding scheme from base
	// Use url.Parse and ResolveReference
	baseURL, err := url.Parse(base)
	if err != nil {
		return ref
	}
	refURL, err := url.Parse(ref)
	if err != nil {
		return ref
	}
	resolved := baseURL.ResolveReference(refURL)
	return resolved.String()
}

