type FileOutput struct {
	InputPath string
	Content   string
}

func computeTargets(inputFiles []string, outputDir string) []string {
	// Compute output file paths for each input file, handling collisions with hash
	// outputDir ends with "/"
	// For each input file, baseName = filename without ext + ".md"
	// Need to handle collisions: first occurrence keeps base, subsequent get base.<hash>.md where hash is sha256 of relative path to common ancestor

	// Determine common ancestor
	common := commonPath(inputFiles)
	// Keep map of used output names
	used := make(map[string]int) // output base name -> count
	// Also need to keep track of which input files map to which output to compute hash for collisions
	// First, compute all target basenames
	type entry struct {
		inputPath string
		base      string // e.g., "a.md"
		relPath   string // relative to common
		target    string // final output path
	}
	var entries []entry
	for _, f := range inputFiles {
		base := filepath.Base(f)
		ext := filepath.Ext(base)
		stem := strings.TrimSuffix(base, ext)
		if stem == "" {
			stem = base
		}
		outBase := stem + ".md"
		rel, err := filepath.Rel(common, f)
		if err != nil {
			rel = f
		}
		entries = append(entries, entry{inputPath: f, base: outBase, relPath: rel})
	}

	// Sort entries by inputPath to have deterministic order (inputFiles already sorted)
	sort.Slice(entries, func(i, j int) bool {
		return entries[i].inputPath < entries[j].inputPath
	})

	// Now assign targets
	var targets []string
	usedCount := make(map[string]int)
	for _, e := range entries {
		if usedCount[e.base] == 0 {
			// First occurrence
			usedCount[e.base] = 1
			targets = append(targets, filepath.Join(outputDir, e.base))
		} else {
			// Collision: compute hash
			hash := sha256.Sum256([]byte(e.relPath))
			hexStr := hex.EncodeToString(hash[:])[:10]
			// Insert hash before .md
			stem := strings.TrimSuffix(e.base, ".md")
			newBase := fmt.Sprintf("%s.%s.md", stem, hexStr)
			// Ensure newBase not already used? If still collision, maybe need to handle further? For simplicity, if newBase exists in used, we could generate further, but original likely handles.
			// Check if newBase already used, if so, maybe generate with more hash? But for now, use it.
			// Also need to handle if newBase collides with another file's base? e.g., if a file named "a.<hash>.md" already exists as input? Unlikely.
			// For safety, loop to find unique
			for {
				if _, ok := used[newBase]; !ok {
					break
				}
				// If collision, maybe use longer hash or add counter? But we will just append more?
				// For simplicity, break
				break
			}
			used[newBase] = 1
			usedCount[e.base]++
			targets = append(targets, filepath.Join(outputDir, newBase))
		}
		used[e.base] = 1
	}

	return targets
}

func commonPath(paths []string) string {
	if len(paths) == 0 {
		return ""
	}
	if len(paths) == 1 {
		return filepath.Dir(paths[0])
	}
	// Use common prefix
	// Split each path into components
	// Find common ancestor directory
	// Use filepath.Dir for each and then find common
	// Actually we need common ancestor of all file paths, not just directories? The common ancestor should be directory that contains all files.
	// For paths like "/tmp/in1/a.html" and "/tmp/in2/a.html", common ancestor is "/tmp"
	// Using os commonpath logic: find longest common prefix of directories
	// Approach: take first path's dir, then iteratively find common with next path's dir
	common := filepath.Dir(paths[0])
	for _, p := range paths[1:] {
		dir := filepath.Dir(p)
		common = commonDir(common, dir)
		if common == "" || common == "." {
			// No common
			break
		}
	}
	return common
}

func commonDir(a, b string) string {
	// Find common directory between a and b
	// Split by separator
	aParts := strings.Split(filepath.Clean(a), string(filepath.Separator))
	bParts := strings.Split(filepath.Clean(b), string(filepath.Separator))
	var commonParts []string
	for i := 0; i < len(aParts) && i < len(bParts); i++ {
		if aParts[i] == bParts[i] {
			commonParts = append(commonParts, aParts[i])
		} else {
			break
		}
	}
	if len(commonParts) == 0 {
		return ""
	}
	return strings.Join(commonParts, string(filepath.Separator))
}

