func isListBlock(s string) bool {
	// Check if block starts with "- " or "* " or "+ " or ordered like "1. "
	// Also after trimming leading spaces?
	lines := strings.Split(s, "\n")
	if len(lines) == 0 {
		return false
	}
	first := strings.TrimSpace(lines[0])
	if strings.HasPrefix(first, "- ") || strings.HasPrefix(first, "* ") || strings.HasPrefix(first, "+ ") {
		return true
	}
	// Ordered list: e.g., "1. ", "2. ", "10. "
	re := regexp.MustCompile(`^\d+\.\s`)
	return re.MatchString(first)
}

func filterTopMost(nodes []*html.Node) []*html.Node {
	// Keep only nodes that are not descendant of another node in list
	var filtered []*html.Node
	for _, n := range nodes {
		isDescendant := false
		for _, other := range nodes {
			if n == other {
				continue
			}
			// Check if n is descendant of other
			for p := n.Parent; p != nil; p = p.Parent {
				if p == other {
					isDescendant = true
					break
				}
			}
			if isDescendant {
				break
			}
		}
		if !isDescendant {
			filtered = append(filtered, n)
		}
	}
	// Sort by document order? For simplicity, keep order as found, but need to sort by position
	// We'll sort by depth-first order? Our find function already does depth-first, so filtered should be in order
	return filtered
}

func findBody(n *html.Node) *html.Node {
	if n.Type == html.ElementNode && n.Data == "body" {
		return n
	}
	for c := n.FirstChild; c != nil; c = c.NextSibling {
		if res := findBody(c); res != nil {
			return res
		}
	}
	return nil
}

func matchesSelector(node *html.Node, selector string) bool {
	if node.Type != html.ElementNode {
		return false
	}
	// Support comma separated
	parts := strings.Split(selector, ",")
	for _, part := range parts {
		part = strings.TrimSpace(part)
		if part == "" {
			continue
		}
		if matchesSingleSelector(node, part) {
			return true
		}
	}
	return false
}

func matchesSingleSelector(node *html.Node, sel string) bool {
	sel = strings.TrimSpace(sel)
	if sel == "" {
		return false
	}
	if sel == "*" {
		return true
	}
	// Simple parsing: support tag, .class, #id, tag.class, tag#id, .class1.class2, etc, and attribute selectors? For our needs, support .class and tag and combinations
	// Also support descendant? Probably not needed, but we can support simple descendant via space? For simplicity, we will support only simple selectors without combinators? But we need to support ".a, .b" already handled by comma, and maybe descendant like ".content" containing <a>?

	// For now, we will implement:
	// - If selector contains space, we will check if node matches last part? Actually for include selector, they use ".content" to select div with class content. That is simple.
	// - For more complex like "div p", we could support descendant by checking if node matches last part and has ancestor matching previous parts? But to keep simple, we will treat space as descendant and require that node matches last token and has ancestor matching previous tokens.

	// Split by space for descendant
	// For simplicity, handle only single level descendant? But we can recursively check.

	// If selector contains ">" child combinator, ignore? Not needed.

	// For now, check if selector contains space, split and handle descendant
	if strings.Contains(sel, " ") {
		// Split by spaces
		tokens := strings.Fields(sel)
		// Last token must match current node
		last := tokens[len(tokens)-1]
		if !matchesSimpleToken(node, last) {
			return false
		}
		// For preceding tokens, need to find ancestors matching
		// We will walk up ancestors and try to match tokens in reverse order
		// This is simplified: require each preceding token to match some ancestor in order
		anc := node.Parent
		idx := len(tokens) - 2
		for anc != nil && idx >= 0 {
			if matchesSimpleToken(anc, tokens[idx]) {
				idx--
			}
			anc = anc.Parent
		}
		return idx < 0
	}

	return matchesSimpleToken(node, sel)
}

func matchesSimpleToken(node *html.Node, token string) bool {
	if token == "*" {
		return true
	}
	// Token may be like "div", ".a", "#id", "div.a", "div#id", "div.a#b", ".a#b", etc
	// Parse tag, classes, id

	// Extract tag, id, classes
	// Find id
	var tag string
	var id string
	var classes []string

	// Check for #id
	if strings.Contains(token, "#") {
		parts := strings.SplitN(token, "#", 2)
		// parts[0] may contain tag and classes before #
		tagPart := parts[0]
		idAndRest := parts[1]
		// idAndRest may contain "." for classes after id
		if strings.Contains(idAndRest, ".") {
			idParts := strings.SplitN(idAndRest, ".", 2)
			id = idParts[0]
			// classes after
			rest := idParts[1]
			classes = append(classes, strings.Split(rest, ".")...)
		} else {
			id = idAndRest
		}
		// tagPart may contain classes
		if strings.Contains(tagPart, ".") {
			tp := strings.Split(tagPart, ".")
			if tp[0] != "" {
				tag = tp[0]
			}
			for _, c := range tp[1:] {
				if c != "" {
					classes = append(classes, c)
				}
			}
		} else {
			if tagPart != "" {
				tag = tagPart
			}
		}
	} else {
		// No id, check for classes
		if strings.Contains(token, ".") {
			parts := strings.Split(token, ".")
			if parts[0] != "" {
				tag = parts[0]
			}
			for _, c := range parts[1:] {
				if c != "" {
					classes = append(classes, c)
				}
			}
		} else {
			// Only tag
			tag = token
		}
	}

	// If tag is present and not "*", check
	if tag != "" && tag != "*" {
		if node.Data != tag {
			return false
		}
	}
	// Check id
	if id != "" {
		if getAttr(node, "id") != id {
			return false
		}
	}
	// Check classes
	if len(classes) > 0 {
		classAttr := getAttr(node, "class")
		// classAttr is space-separated list
		nodeClasses := strings.Fields(classAttr)
		classSet := make(map[string]bool)
		for _, c := range nodeClasses {
			classSet[c] = true
		}
		for _, needed := range classes {
			if !classSet[needed] {
				return false
			}
		}
	}
	return true
}

func getAttr(n *html.Node, key string) string {
	for _, a := range n.Attr {
		if a.Key == key {
			return a.Val
		}
	}
	return ""
}

