        show the version of html2markdown and exit

    --help

    --input PATH
        Input file, directory, or glob pattern (instead of stdin)

    --output PATH
        Output file or directory (instead of stdout)

    --output-overwrite
        Replace existing files

    If --input is a directory or glob pattern, --output must be a directory.



    --domain
        The url of the web page, used to convert relative links to absolute links.

    --exclude-selector
        css query selector to exclude parts of the input

    --include-selector
        css query selector to only include parts of the input

    --opt-strong-delimiter
        Make bold text. Should <strong> be indicated by two asterisks or two underscores?
        "**" or "__" (default: "**")

    --opt-table-cell-padding-behavior
        [for --plugin-table] whether cells in the tables should include extra padding for visual continuity: "aligned", "minimal", or "none"

    --opt-table-header-promotion
        [for --plugin-table] first row should be treated as a header

    --opt-table-newline-behavior
        [for --plugin-table] how tables containing newlines should be handled: "skip" or "preserve"

    --opt-table-presentation-tables
        [for --plugin-table] whether tables with role="presentation" should be converted

    --opt-table-skip-empty-rows
        [for --plugin-table] omit empty rows from the output

    --opt-table-span-cell-behavior
        [for --plugin-table] how colspan/rowspan should be rendered: "empty" or "mirror"

    --plugin-strikethrough
        enable the plugin ~~strikethrough~~

    --plugin-table
        enable the plugin table



For more information visit the documentation:
https://github.com/Johanneskaufmann/html-to-markdown
`

const versionText = `html2markdown

GitVersion:  dev
GitCommit:   none
BuildDate:   unknown
`

func printError(format string, args ...interface{}) {
	fmt.Fprintf(os.Stderr, "\n"+format+"\n\n", args...)
}

func main() {
	args := os.Args[1:]

	for _, a := range args {
		if a == "--help" || strings.HasPrefix(a, "--help=") {
			fmt.Print(helpText)
			os.Exit(0)
		}
	}
	for _, a := range args {
		if a == "-v" || a == "--version" || strings.HasPrefix(a, "--version") || strings.HasPrefix(a, "-v=") {
			// For --version=maybe, should it show version or error? Original would show version even with =? We treat as version for simplicity, but need to check bool parsing for version?
			// Actually if --version=maybe, original might error invalid bool? Let's test: we didn't. For now, if arg starts with --version, show version.
			// However, if --version is provided as "--version=maybe", our earlier logic for bool parse would error. But we already handled version before flag parsing, so we show version.
			// This matches our earlier observation that version works without stdin.
			fmt.Print(versionText)
			os.Exit(0)
		}
	}

	type flagSpec struct {
		name   string
		isBool bool
	}

	knownFlags := map[string]flagSpec{
		"help":                            {name: "help", isBool: true},
		"version":                         {name: "version", isBool: true},
		"v":                               {name: "version", isBool: true},
		"input":                           {name: "input", isBool: false},
		"output":                          {name: "output", isBool: false},
		"output-overwrite":                {name: "output-overwrite", isBool: true},
		"domain":                          {name: "domain", isBool: false},
		"exclude-selector":                {name: "exclude-selector", isBool: false},
		"include-selector":                {name: "include-selector", isBool: false},
		"opt-strong-delimiter":            {name: "opt-strong-delimiter", isBool: false},
		"opt-table-cell-padding-behavior": {name: "opt-table-cell-padding-behavior", isBool: false},
		"opt-table-header-promotion":      {name: "opt-table-header-promotion", isBool: true},
		"opt-table-newline-behavior":      {name: "opt-table-newline-behavior", isBool: false},
		"opt-table-presentation-tables":   {name: "opt-table-presentation-tables", isBool: true},
		"opt-table-skip-empty-rows":       {name: "opt-table-skip-empty-rows", isBool: true},
		"opt-table-span-cell-behavior":    {name: "opt-table-span-cell-behavior", isBool: false},
		"plugin-strikethrough":            {name: "plugin-strikethrough", isBool: true},
		"plugin-table":                    {name: "plugin-table", isBool: true},
	}

	flagValues := make(map[string]string)
	flagBoolValues := make(map[string]bool)
	flagSet := make(map[string]bool)

	var positional []string

	getSpec := func(name string) (flagSpec, bool) {
		spec, ok := knownFlags[name]
		return spec, ok
	}

	i := 0
	for i < len(args) {
		arg := args[i]
		if arg == "--" {
			i++
			for ; i < len(args); i++ {
				positional = append(positional, args[i])
			}
			break
		}
		if strings.HasPrefix(arg, "-") {
			var namePart string
			var valuePart *string
			originalArg := arg
			if strings.Contains(arg, "=") {
				parts := strings.SplitN(arg, "=", 2)
				namePart = parts[0]
				v := parts[1]
				valuePart = &v
			} else {
				namePart = arg
			}
			trimmed := strings.TrimLeft(namePart, "-")
			if trimmed == "" {
				positional = append(positional, arg)
				i++
				continue
			}
			spec, ok := getSpec(trimmed)
			if !ok {
				printError("error: unknown flag: %s", originalArg)
				os.Exit(1)
			}
			if spec.isBool {
				if valuePart != nil {
					v := *valuePart
					b, err := parseBool(v)
					if err != nil {
						printError("error: invalid boolean value \"%s\" for -%s: parse error", v, spec.name)
						os.Exit(1)
					}
					flagBoolValues[spec.name] = b
					flagSet[spec.name] = true
				} else {
					if i+1 < len(args) && !strings.HasPrefix(args[i+1], "-") {
						nextVal := args[i+1]
						if _, err := parseBool(nextVal); err == nil {
							b, _ := parseBool(nextVal)
							flagBoolValues[spec.name] = b
							flagSet[spec.name] = true
							i += 2
							continue
						}
					}
					flagBoolValues[spec.name] = true
					flagSet[spec.name] = true
				}
				i++
			} else {
				var val string
				if valuePart != nil {
					val = *valuePart
					flagValues[spec.name] = val
					flagSet[spec.name] = true
					i++
				} else {
					if i+1 >= len(args) {
						printError("error: flag needs an argument: -%s", spec.name)
						os.Exit(1)
					}
					next := args[i+1]
					if strings.HasPrefix(next, "-") {
						printError("error: flag needs an argument: -%s", spec.name)
						os.Exit(1)
					}
					val = next
					flagValues[spec.name] = val
					flagSet[spec.name] = true
					i += 2
				}
			}
		} else {
			positional = append(positional, arg)
			i++
		}
	}

	if len(positional) > 0 {
		joined := strings.Join(positional, " ")
		fmt.Fprintf(os.Stderr, "\nerror: unknown arguments: %s\n\nHere is how you can use the CLI:\n\n    echo \"<strong>important</strong>\" | html2markdown\n\n", joined)
		os.Exit(1)
	}

	if flagSet["include-selector"] {
		v := flagValues["include-selector"]
		if err := validateSelector(v); err != nil {
			printError("error: invalid value \"%s\" for flag -include-selector: %s", v, err.Error())
			os.Exit(1)
		}
	}
	if flagSet["exclude-selector"] {
		v := flagValues["exclude-selector"]
		if err := validateSelector(v); err != nil {
			printError("error: invalid value \"%s\" for flag -exclude-selector: %s", v, err.Error())
			os.Exit(1)
		}
	}

	tableOptFlags := []string{
		"opt-table-cell-padding-behavior",
		"opt-table-header-promotion",
		"opt-table-newline-behavior",
		"opt-table-presentation-tables",
		"opt-table-skip-empty-rows",
		"opt-table-span-cell-behavior",
	}
	if !flagSet["plugin-table"] || !flagBoolValues["plugin-table"] {
		for _, f := range tableOptFlags {
			if flagSet[f] {
				printError("error: --%s requires --plugin-table to be enabled", f)
				os.Exit(1)
			}
		}
	}

	var inputFiles []string
	var inputPattern string
	if flagSet["input"] {
		inputPattern = flagValues["input"]
		hasGlob := strings.ContainsAny(inputPattern, "*?[]{}")
		if hasGlob {
			matches, err := filepath.Glob(inputPattern)
			if err != nil {
				fmt.Fprintf(os.Stderr, "\nerror: no files found matching pattern \"%s\"\n\nHere is how you can use a glob to match multiple files:\n\n    html2markdown --input \"src/*.html\" --output \"dist/\"\n\n", inputPattern)
				os.Exit(1)
			}
			var filtered []string
			for _, m := range matches {
				info, err := os.Stat(m)
				if err != nil {
					continue
				}
				if info.Mode().IsRegular() {
					filtered = append(filtered, m)
				}
			}
			if len(filtered) == 0 {
				fmt.Fprintf(os.Stderr, "\nerror: no files found matching pattern \"%s\"\n\nHere is how you can use a glob to match multiple files:\n\n    html2markdown --input \"src/*.html\" --output \"dist/\"\n\n", inputPattern)
				os.Exit(1)
			}
			inputFiles = filtered
		} else {
			info, err := os.Stat(inputPattern)
			if err != nil {
				fmt.Fprintf(os.Stderr, "\nerror: no files found matching pattern \"%s\"\n\nHere is how you can use a glob to match multiple files:\n\n    html2markdown --input \"src/*.html\" --output \"dist/\"\n\n", inputPattern)
				os.Exit(1)
			}
			if info.IsDir() {
				fmt.Fprintf(os.Stderr, "\nerror: input path \"%s\" is a directory, not a file\n\nHere is how you can use a glob to match multiple files:\n\n    html2markdown --input \"src/*.html\" --output \"dist/\"\n\n", inputPattern)
				os.Exit(1)
			}
			if !info.Mode().IsRegular() {
				fmt.Fprintf(os.Stderr, "\nerror: no files found matching pattern \"%s\"\n\nHere is how you can use a glob to match multiple files:\n\n    html2markdown --input \"src/*.html\" --output \"dist/\"\n\n", inputPattern)
				os.Exit(1)
			}
			inputFiles = []string{inputPattern}
		}
		sort.Strings(inputFiles)
	} else {
		st, err := os.Stdin.Stat()
		if err != nil {
			fmt.Fprintf(os.Stderr, "\nerror: the html input should be piped into the cli\n\nHere is how you can use the CLI:\n\n    echo \"<strong>important</strong>\" | html2markdown\n\n")
			os.Exit(1)
		}
		if (st.Mode() & os.ModeCharDevice) != 0 {
			fmt.Fprintf(os.Stderr, "\nerror: the html input should be piped into the cli\n\nHere is how you can use the CLI:\n\n    echo \"<strong>important</strong>\" | html2markdown\n\n")
			os.Exit(1)
		}
	}

	strongDelim := "**"
	if flagSet["opt-strong-delimiter"] {
		strongDelim = flagValues["opt-strong-delimiter"]
		if strongDelim != "**" && strongDelim != "__" {
			printError("error: invalid value for --opt-strong-delimiter=\"%s\" must be exactly 2 characters of \"**\" or \"__\"", strongDelim)
			os.Exit(1)
		}
	}

	if flagSet["plugin-table"] && flagBoolValues["plugin-table"] {
		if flagSet["opt-table-cell-padding-behavior"] {
			v := flagValues["opt-table-cell-padding-behavior"]
			if v != "aligned" && v != "minimal" && v != "none" {
				printError("error: error while initializing \"table\" plugin: unknown value \"%s\" for cell padding behavior", v)
				os.Exit(1)
			}
		}
		if flagSet["opt-table-span-cell-behavior"] {
			v := flagValues["opt-table-span-cell-behavior"]
			if v != "empty" && v != "mirror" {
				printError("error: error while initializing \"table\" plugin: unknown value \"%s\" for span cell behavior", v)
				os.Exit(1)
			}
		}
		if flagSet["opt-table-newline-behavior"] {
			v := flagValues["opt-table-newline-behavior"]
			if v != "skip" && v != "preserve" {
				printError("error: error while initializing \"table\" plugin: unknown value \"%s\" for newline behavior", v)
				os.Exit(1)
			}
		}
	}

	// Options for converter
	domain := ""
	if flagSet["domain"] {
		domain = flagValues["domain"]
	}
	includeSelector := ""
	if flagSet["include-selector"] {
		includeSelector = flagValues["include-selector"]
	}
	excludeSelector := ""
	if flagSet["exclude-selector"] {
		excludeSelector = flagValues["exclude-selector"]
	}
	cellPadding := "aligned"
	if flagSet["opt-table-cell-padding-behavior"] {
		cellPadding = flagValues["opt-table-cell-padding-behavior"]
	}
	headerPromotion := false
	if flagSet["opt-table-header-promotion"] {
		headerPromotion = flagBoolValues["opt-table-header-promotion"]
	}
	newlineBehavior := "skip"
	if flagSet["opt-table-newline-behavior"] {
		newlineBehavior = flagValues["opt-table-newline-behavior"]
	}
	presentationTables := false
	if flagSet["opt-table-presentation-tables"] {
		presentationTables = flagBoolValues["opt-table-presentation-tables"]
	}
	skipEmptyRows := false
	if flagSet["opt-table-skip-empty-rows"] {
		skipEmptyRows = flagBoolValues["opt-table-skip-empty-rows"]
	}
	spanBehavior := "empty"
	if flagSet["opt-table-span-cell-behavior"] {
		spanBehavior = flagValues["opt-table-span-cell-behavior"]
	}
	strikethrough := false
	if flagSet["plugin-strikethrough"] {
		strikethrough = flagBoolValues["plugin-strikethrough"]
	}
	tablePlugin := false
	if flagSet["plugin-table"] {
		tablePlugin = flagBoolValues["plugin-table"]
	}

	converter := NewConverter(ConverterOptions{
		StrongDelimiter:    strongDelim,
		Domain:             domain,
		IncludeSelector:    includeSelector,
		ExcludeSelector:    excludeSelector,
		CellPadding:        cellPadding,
		HeaderPromotion:    headerPromotion,
		NewlineBehavior:    newlineBehavior,
		PresentationTables: presentationTables,
		SkipEmptyRows:      skipEmptyRows,
		SpanBehavior:       spanBehavior,
		Strikethrough:      strikethrough,
		TablePlugin:        tablePlugin,
	})

	type FileOutput struct {
		InputPath string
		Content   string
	}
	var outputs []FileOutput

	if len(inputFiles) > 0 {
		for _, fpath := range inputFiles {
			data, err := os.ReadFile(fpath)
			if err != nil {
				fmt.Fprintf(os.Stderr, "error reading file %s: %v\n", fpath, err)
				os.Exit(1)
			}
			md := converter.Convert(string(data))
			outputs = append(outputs, FileOutput{InputPath: fpath, Content: md})
		}

		outputPath := ""
		if flagSet["output"] {
			outputPath = flagValues["output"]
		}
		outputOverwrite := false
		if flagSet["output-overwrite"] {
			outputOverwrite = flagBoolValues["output-overwrite"]
		}

		if len(inputFiles) == 1 && outputPath == "" {
			fmt.Print(outputs[0].Content)
			os.Exit(0)
		}

		if len(inputFiles) > 1 && outputPath == "" {
			fmt.Fprintf(os.Stderr, "\nerror: when processing multiple input files --output needs to be a directory\n\nHere is how you can use a glob to match multiple files:\n\n    html2markdown --input \"src/*.html\" --output \"dist/\"\n\n")
			os.Exit(1)
		}

		if outputPath == "" {
			fmt.Print(outputs[0].Content)
			os.Exit(0)
		}

		isDirOutput := strings.HasSuffix(outputPath, "/")

		if len(inputFiles) > 1 && !isDirOutput {
			base := filepath.Base(outputPath)
			fmt.Fprintf(os.Stderr, "\nerror: when processing multiple input files, --output \"%s\" must end with \"%s/\" to indicate a directory\n\n", base, base)
			os.Exit(1)
		}

		if isDirOutput {
			info, err := os.Stat(outputPath)
			if err == nil {
				if !info.IsDir() {
					fmt.Fprintf(os.Stderr, "\nerror: mkdir %s: file exists\n\n", outputPath)
					os.Exit(1)
				}
				targets := computeTargets(inputFiles, outputPath)
				for _, t := range targets {
					if _, err := os.Stat(t); err == nil {
						if !outputOverwrite {
							fmt.Fprintf(os.Stderr, "\nerror: output path \"%s\" already exists. Use --output-overwrite to replace existing files\n\n", outputPath)
							os.Exit(1)
						}
					}
				}
			} else {
				err := os.MkdirAll(outputPath, 0755)
				if err != nil {
					fmt.Fprintf(os.Stderr, "\nerror: %v\n\n", err)
					os.Exit(1)
				}
			}
			targets := computeTargets(inputFiles, outputPath)
			os.MkdirAll(outputPath, 0755)
			for i, tpath := range targets {
				dir := filepath.Dir(tpath)
				os.MkdirAll(dir, 0755)
				err := os.WriteFile(tpath, []byte(outputs[i].Content), 0644)
				if err != nil {
					fmt.Fprintf(os.Stderr, "error writing file %s: %v\n", tpath, err)
					os.Exit(1)
				}
			}
			os.Exit(0)
		} else {
			info, err := os.Stat(outputPath)
			if err == nil {
				if info.IsDir() {
					base := filepath.Base(outputPath)
					fmt.Fprintf(os.Stderr, "\nerror: path \"%s\" exists and is a directory, did you mean \"%s/\"?\n\nThe --output must end with \"/\" to indicate a directory\n\n", base, base)
					os.Exit(1)
				}
				if !outputOverwrite {
					fmt.Fprintf(os.Stderr, "\nerror: output path \"%s\" already exists. Use --output-overwrite to replace existing files\n\n", outputPath)
					os.Exit(1)
				}
			}
			parent := filepath.Dir(outputPath)
			if parent != "." && parent != "" {
				os.MkdirAll(parent, 0755)
			}
			err = os.WriteFile(outputPath, []byte(outputs[0].Content), 0644)
			if err != nil {
				fmt.Fprintf(os.Stderr, "error writing file %s: %v\n", outputPath, err)
				os.Exit(1)
			}
			os.Exit(0)
		}
	} else {
		data, err := io.ReadAll(os.Stdin)
		if err != nil {
			fmt.Fprintf(os.Stderr, "error reading stdin: %v\n", err)
			os.Exit(1)
		}
		md := converter.Convert(string(data))
		outputPath := ""
		if flagSet["output"] {
			outputPath = flagValues["output"]
		}
		outputOverwrite := false
		if flagSet["output-overwrite"] {
			outputOverwrite = flagBoolValues["output-overwrite"]
		}
		if outputPath == "" {
			fmt.Print(md)
			os.Exit(0)
		}
		isDirOutput := strings.HasSuffix(outputPath, "/")
		if isDirOutput {
			info, err := os.Stat(outputPath)
			if err == nil && !info.IsDir() {
				fmt.Fprintf(os.Stderr, "\nerror: mkdir %s: file exists\n\n", outputPath)
				os.Exit(1)
			}
			os.MkdirAll(outputPath, 0755)
			target := filepath.Join(outputPath, "index.md")
			if _, err := os.Stat(target); err == nil && !outputOverwrite {
				fmt.Fprintf(os.Stderr, "\nerror: output path \"%s\" already exists. Use --output-overwrite to replace existing files\n\n", outputPath)
				os.Exit(1)
			}
			os.WriteFile(target, []byte(md), 0644)
			os.Exit(0)
		} else {
			info, err := os.Stat(outputPath)
			if err == nil {
				if info.IsDir() {
					base := filepath.Base(outputPath)
					fmt.Fprintf(os.Stderr, "\nerror: path \"%s\" exists and is a directory, did you mean \"%s/\"?\n\nThe --output must end with \"/\" to indicate a directory\n\n", base, base)
					os.Exit(1)
				}
				if !outputOverwrite {
					fmt.Fprintf(os.Stderr, "\nerror: output path \"%s\" already exists. Use --output-overwrite to replace existing files\n\n", outputPath)
					os.Exit(1)
				}
			}
			parent := filepath.Dir(outputPath)
			if parent != "." && parent != "" {
				os.MkdirAll(parent, 0755)
			}
			os.WriteFile(outputPath, []byte(md), 0644)
			os.Exit(0)
		}
	}
}

func parseBool(s string) (bool, error) {
	return strconv.ParseBool(s)
}

func validateSelector(s string) error {
	if s == "" {
		return fmt.Errorf("invalid css selector: empty string")
	}
	parts := strings.Split(s, ",")
	for _, sel := range parts {
		sel = strings.TrimSpace(sel)
		if sel == "" {
			return fmt.Errorf("invalid css selector: empty string")
		}
		for _, ch := range sel {
			if ch == '!' {
				return fmt.Errorf("expected identifier, found ! instead")
			}
		}
	}
	return nil
}

func computeTargets(inputFiles []string, outputDir string) []string {
	common := commonPath(inputFiles)
	used := make(map[string]int)
	type entry struct {
		inputPath string
		base      string
		relPath   string
	}
	var entries []entry
	for _, f := range inputFiles {
		base := filepath.Base(f)
		ext := filepath.Ext(base)
		stem := strings.TrimSuffix(base, ext)
		if stem == "" {
			stem = base
		}
		outBase := stem + ".md"
		rel, err := filepath.Rel(common, f)
		if err != nil {
			rel = f
		}
		entries = append(entries, entry{inputPath: f, base: outBase, relPath: rel})
	}
	sort.Slice(entries, func(i, j int) bool {
		return entries[i].inputPath < entries[j].inputPath
	})
	var targets []string
	usedCount := make(map[string]int)
	for _, e := range entries {
		if usedCount[e.base] == 0 {
			usedCount[e.base] = 1
			targets = append(targets, filepath.Join(outputDir, e.base))
			used[e.base] = 1
		} else {
			h := sha256.Sum256([]byte(e.relPath))
			hexStr := hex.EncodeToString(h[:])[:10]
			stem := strings.TrimSuffix(e.base, ".md")
			newBase := fmt.Sprintf("%s.%s.md", stem, hexStr)
			used[newBase] = 1
			usedCount[e.base]++
			targets = append(targets, filepath.Join(outputDir, newBase))
		}
	}
	return targets
}

func commonPath(paths []string) string {
	if len(paths) == 0 {
		return ""
	}
	if len(paths) == 1 {
		return filepath.Dir(paths[0])
	}
	common := filepath.Dir(paths[0])
	for _, p := range paths[1:] {
		dir := filepath.Dir(p)
		common = commonDir(common, dir)
		if common == "" || common == "." {
			break
		}
	}
	return common
}

func commonDir(a, b string) string {
	aParts := strings.Split(filepath.Clean(a), string(filepath.Separator))
	bParts := strings.Split(filepath.Clean(b), string(filepath.Separator))
	var commonParts []string
	for i := 0; i < len(aParts) && i < len(bParts); i++ {
		if aParts[i] == bParts[i] {
			commonParts = append(commonParts, aParts[i])
		} else {
			break
		}
	}
	if len(commonParts) == 0 {
		return ""
	}
	return strings.Join(commonParts, string(filepath.Separator))
}

type ConverterOptions struct {
	StrongDelimiter    string
	Domain             string
	IncludeSelector    string
	ExcludeSelector    string
	CellPadding        string
	HeaderPromotion    bool
	NewlineBehavior    string
	PresentationTables bool
	SkipEmptyRows      bool
	SpanBehavior       string
	Strikethrough      bool
	TablePlugin        bool
}

type Converter struct {
	opts ConverterOptions
}

func NewConverter(opts ConverterOptions) *Converter {
	return &Converter{opts: opts}
}

func (c *Converter) Convert(htmlContent string) string {
	doc, err := html.Parse(strings.NewReader(htmlContent))
	if err != nil {
		return ""
	}
	body := findBody(doc)
	if body == nil {
		body = doc
	}
	if c.opts.ExcludeSelector != "" {
		var toRemove []*html.Node
		var walk func(*html.Node)
		walk = func(n *html.Node) {
			if n.Type == html.ElementNode {
				if matchesSelector(n, c.opts.ExcludeSelector) {
					toRemove = append(toRemove, n)
					return
				}
			}
			for child := n.FirstChild; child != nil; child = child.NextSibling {
				walk(child)
			}
		}
		walk(body)
		for _, n := range toRemove {
			if n.Parent != nil {
				n.Parent.RemoveChild(n)
			}
		}
	}
	var includedNodes []*html.Node
	if c.opts.IncludeSelector != "" {
		var find func(*html.Node)
		find = func(n *html.Node) {
			if n.Type == html.ElementNode {
				if matchesSelector(n, c.opts.IncludeSelector) {
					includedNodes = append(includedNodes, n)
				}
			}
			for child := n.FirstChild; child != nil; child = child.NextSibling {
				find(child)
			}
		}
		find(body)
		if len(includedNodes) == 0 {
			return ""
		}
		includedNodes = filterTopMost(includedNodes)
		var blocks []string
		for _, n := range includedNodes {
			md := c.convertNode(n, 0, false)
			trimmed := strings.TrimSpace(md)
			if trimmed != "" {
				blocks = append(blocks, trimmed)
			}
		}
		result := strings.Join(blocks, "\n\n")
		if result != "" {
			result += "\n"
		}
		return result
	}
	var blocks []string
	for child := body.FirstChild; child != nil; child = child.NextSibling {
		md := c.convertNode(child, 0, false)
		trimmed := strings.TrimSpace(md)
		if trimmed != "" {
			blocks = append(blocks, trimmed)
		}
	}
	var finalBlocks []string
	var prevIsList bool
	for _, b := range blocks {
		trim := strings.TrimSpace(b)
		isList := isListBlock(trim)
		if prevIsList && isList {
			finalBlocks = append(finalBlocks, "<!--THE END-->")
		}
		finalBlocks = append(finalBlocks, trim)
		prevIsList = isList
	}
	result := strings.Join(finalBlocks, "\n\n")
	if result != "" {
		result += "\n"
	}
	return result
}

func isListBlock(s string) bool {
	lines := strings.Split(s, "\n")
	if len(lines) == 0 {
		return false
	}
	first := strings.TrimSpace(lines[0])
	if strings.HasPrefix(first, "- ") {
		return true
	}
	re := regexp.MustCompile(`^\d+\.\s`)
	return re.MatchString(first)
}

func filterTopMost(nodes []*html.Node) []*html.Node {
	var filtered []*html.Node
	for _, n := range nodes {
		isDesc := false
		for _, other := range nodes {
			if n == other {
				continue
			}
			for p := n.Parent; p != nil; p = p.Parent {
				if p == other {
					isDesc = true
					break
				}
			}
			if isDesc {
				break
			}
		}
		if !isDesc {
			filtered = append(filtered, n)
		}
	}
	return filtered
}

func findBody(n *html.Node) *html.Node {
	if n.Type == html.ElementNode && n.Data == "body" {
		return n
	}
	for c := n.FirstChild; c != nil; c = c.NextSibling {
		if res := findBody(c); res != nil {
			return res
		}
	}
	return nil
}

func matchesSelector(node *html.Node, selector string) bool {
	if node.Type != html.ElementNode {
		return false
	}
	parts := strings.Split(selector, ",")
	for _, part := range parts {
		part = strings.TrimSpace(part)
		if part == "" {
			continue
		}
		if matchesSingleSelector(node, part) {
			return true
		}
	}
	return false
}

func matchesSingleSelector(node *html.Node, sel string) bool {
	sel = strings.TrimSpace(sel)
	if sel == "" {
		return false
	}
	if sel == "*" {
		return true
	}
	if strings.Contains(sel, " ") {
		tokens := strings.Fields(sel)
		last := tokens[len(tokens)-1]
		if !matchesSimpleToken(node, last) {
			return false
		}
		anc := node.Parent
		idx := len(tokens) - 2
		for anc != nil && idx >= 0 {
			if matchesSimpleToken(anc, tokens[idx]) {
				idx--
			}
			anc = anc.Parent
		}
		return idx < 0
	}
	return matchesSimpleToken(node, sel)
}

func matchesSimpleToken(node *html.Node, token string) bool {
	if token == "*" {
		return true
	}
	var tag string
	var id string
	var classes []string
	if strings.Contains(token, "#") {
		parts := strings.SplitN(token, "#", 2)
		tagPart := parts[0]
		idAndRest := parts[1]
		if strings.Contains(idAndRest, ".") {
			idParts := strings.SplitN(idAndRest, ".", 2)
			id = idParts[0]
			rest := idParts[1]
			classes = append(classes, strings.Split(rest, ".")...)
		} else {
			id = idAndRest
		}
		if strings.Contains(tagPart, ".") {
			tp := strings.Split(tagPart, ".")
			if tp[0] != "" {
				tag = tp[0]
			}
			for _, c := range tp[1:] {
				if c != "" {
					classes = append(classes, c)
				}
			}
		} else {
			if tagPart != "" {
				tag = tagPart
			}
		}
	} else {
		if strings.Contains(token, ".") {
			parts := strings.Split(token, ".")
			if parts[0] != "" {
				tag = parts[0]
			}
			for _, c := range parts[1:] {
				if c != "" {
					classes = append(classes, c)
				}
			}
		} else {
			tag = token
		}
	}
	if tag != "" && tag != "*" {
		if node.Data != tag {
			return false
		}
	}
	if id != "" {
		if getAttr(node, "id") != id {
			return false
		}
	}
	if len(classes) > 0 {
		classAttr := getAttr(node, "class")
		nodeClasses := strings.Fields(classAttr)
		classSet := make(map[string]bool)
		for _, c := range nodeClasses {
			classSet[c] = true
		}
		for _, needed := range classes {
			if !classSet[needed] {
				return false
			}
		}
	}
	return true
}

func getAttr(n *html.Node, key string) string {
	for _, a := range n.Attr {
		if a.Key == key {
			return a.Val
		}
	}
	return ""
}

func (c *Converter) convertNode(n *html.Node, indent int, inTable bool) string {
	if n.Type == html.TextNode {
		text := n.Data
		if n.Parent != nil && strings.ToLower(n.Parent.Data) == "pre" {
			return text
		}
		return text
	}
	if n.Type != html.ElementNode {
		return ""
	}
	tag := strings.ToLower(n.Data)
	if tag == "script" || tag == "style" || tag == "head" || tag == "title" || tag == "meta" || tag == "link" {
		return ""
	}
	if !c.opts.TablePlugin {
		if tag == "table" || tag == "tr" || tag == "td" || tag == "th" || tag == "tbody" || tag == "thead" || tag == "tfoot" || tag == "colgroup" || tag == "col" || tag == "caption" {
			var sb strings.Builder
			for child := n.FirstChild; child != nil; child = child.NextSibling {
				sb.WriteString(c.convertNode(child, indent, false))
			}
			return sb.String()
		}
	} else {
		if tag == "table" {
			role := getAttr(n, "role")
			if role == "presentation" && !c.opts.PresentationTables {
				var sb strings.Builder
				for child := n.FirstChild; child != nil; child = child.NextSibling {
					sb.WriteString(c.convertNode(child, indent, false))
				}
				return sb.String()
			}
			return c.convertTable(n)
		}
	}

	switch tag {
	case "h1", "h2", "h3", "h4", "h5", "h6":
		level := int(tag[1] - '0')
		inner := c.convertChildren(n, indent, false)
		inner = strings.TrimSpace(inner)
		if inner == "" {
			return ""
		}
		return strings.Repeat("#", level) + " " + inner
	case "p":
		inner := c.convertChildren(n, indent, false)
		inner = strings.TrimSpace(inner)
		if inner == "" {
			return ""
		}
		return inner
	case "strong", "b":
		inner := c.convertChildren(n, indent, false)
		if strings.TrimSpace(inner) == "" {
			return ""
		}
		delim := c.opts.StrongDelimiter
		if delim == "" {
			delim = "**"
		}
		return delim + inner + delim
	case "em", "i":
		inner := c.convertChildren(n, indent, false)
		if strings.TrimSpace(inner) == "" {
			return ""
		}
		return "*" + inner + "*"
	case "s", "del", "strike":
		inner := c.convertChildren(n, indent, false)
		if strings.TrimSpace(inner) == "" {
			return ""
		}
		if c.opts.Strikethrough {
			return "~~" + inner + "~~"
		}
		return inner
	case "code":
		if n.Parent != nil && strings.ToLower(n.Parent.Data) == "pre" {
			var sb strings.Builder
			for child := n.FirstChild; child != nil; child = child.NextSibling {
				if child.Type == html.TextNode {
					sb.WriteString(child.Data)
				} else {
					sb.WriteString(c.convertNode(child, indent, false))
				}
			}
			return sb.String()
		}
		inner := ""
		for child := n.FirstChild; child != nil; child = child.NextSibling {
			if child.Type == html.TextNode {
				inner += child.Data
			} else {
				inner += c.convertNode(child, indent, false)
			}
		}
		return escapeInlineCode(inner)
	case "pre":
		var codeContent string
		var lang string
		for child := n.FirstChild; child != nil; child = child.NextSibling {
			if child.Type == html.ElementNode && strings.ToLower(child.Data) == "code" {
				class := getAttr(child, "class")
				parts := strings.Fields(class)
				for _, p := range parts {
					if strings.HasPrefix(p, "language-") {
						lang = strings.TrimPrefix(p, "language-")
						break
					}
					if strings.HasPrefix(p, "lang-") {
						lang = strings.TrimPrefix(p, "lang-")
						break
					}
				}
				var sb strings.Builder
				for gc := child.FirstChild; gc != nil; gc = gc.NextSibling {
					if gc.Type == html.TextNode {
						sb.WriteString(gc.Data)
					} else {
						sb.WriteString(c.convertNode(gc, indent, false))
					}
				}
				codeContent = sb.String()
				break
			}
		}
		if codeContent == "" {
			var sb strings.Builder
			for child := n.FirstChild; child != nil; child = child.NextSibling {
				if child.Type == html.TextNode {
					sb.WriteString(child.Data)
				} else {
					sb.WriteString(c.convertNode(child, indent, true))
				}
			}
			codeContent = sb.String()
		}
		fence := "```"
		maxTicks := 0
		count := 0
		for _, ch := range codeContent {
			if ch == '`' {
				count++
				if count > maxTicks {
					maxTicks = count
				}
			} else {
				count = 0
			}
		}
		if maxTicks >= 3 {
			fence = strings.Repeat("`", maxTicks+1)
		}
		if lang != "" {
			fence += lang
		}
		var sb strings.Builder
		sb.WriteString(fence)
		sb.WriteString("\n")
		sb.WriteString(codeContent)
		if !strings.HasSuffix(codeContent, "\n") {
			sb.WriteString("\n")
		}
		closing := "```"
		if maxTicks >= 3 {
			closing = strings.Repeat("`", maxTicks+1)
		}
		sb.WriteString(closing)
		return sb.String()
	case "a":
		href := getAttr(n, "href")
		title := getAttr(n, "title")
		inner := c.convertChildren(n, indent, false)
		resolvedHref := href
		if c.opts.Domain != "" {
			resolvedHref = resolveURL(c.opts.Domain, href)
		}
		encodedHref := encodeLinkDestination(resolvedHref)
		escapedText := escapeLinkText(inner)
		if title != "" {
			var titlePart string
			if strings.Contains(title, "\"") && !strings.Contains(title, "'") {
				titlePart = fmt.Sprintf("'%s'", title)
			} else if strings.Contains(title, "'") && !strings.Contains(title, "\"") {
				titlePart = fmt.Sprintf("\"%s\"", title)
			} else if strings.Contains(title, "\"") && strings.Contains(title, "'") {
				escapedTitle := strings.ReplaceAll(title, "\"", "\\\"")
				titlePart = fmt.Sprintf("\"%s\"", escapedTitle)
			} else {
				titlePart = fmt.Sprintf("\"%s\"", title)
			}
			return fmt.Sprintf("[%s](%s %s)", escapedText, encodedHref, titlePart)
		} else {
			return fmt.Sprintf("[%s](%s)", escapedText, encodedHref)
		}
	case "img":
		src := getAttr(n, "src")
		alt := getAttr(n, "alt")
		title := getAttr(n, "title")
		resolvedSrc := src
		if c.opts.Domain != "" {
			resolvedSrc = resolveURL(c.opts.Domain, src)
		}
		encodedSrc := encodeLinkDestination(resolvedSrc)
		escapedAlt := escapeImageAlt(alt)
		if title != "" {
			var titlePart string
			if strings.Contains(title, "\"") && !strings.Contains(title, "'") {
				titlePart = fmt.Sprintf("'%s'", title)
			} else if strings.Contains(title, "'") && !strings.Contains(title, "\"") {
				titlePart = fmt.Sprintf("\"%s\"", title)
			} else if strings.Contains(title, "\"") && strings.Contains(title, "'") {
				escapedTitle := strings.ReplaceAll(title, "\"", "\\\"")
				titlePart = fmt.Sprintf("\"%s\"", escapedTitle)
			} else {
				titlePart = fmt.Sprintf("\"%s\"", title)
			}
			return fmt.Sprintf("![%s](%s %s)", escapedAlt, encodedSrc, titlePart)
		} else {
			return fmt.Sprintf("![%s](%s)", escapedAlt, encodedSrc)
		}
	case "ul":
		var items []string
		for child := n.FirstChild; child != nil; child = child.NextSibling {
			if child.Type == html.ElementNode && strings.ToLower(child.Data) == "li" {
				liContent := c.convertLi(child, indent)
				items = append(items, liContent)
			}
		}
		return strings.Join(items, "\n")
	case "ol":
		start := 1
		startAttr := getAttr(n, "start")
		if startAttr != "" {
			if v, err := strconv.Atoi(startAttr); err == nil {
				start = v
			}
		}
		var items []string
		idx := start
		for child := n.FirstChild; child != nil; child = child.NextSibling {
			if child.Type == html.ElementNode && strings.ToLower(child.Data) == "li" {
				liContent := c.convertLiOrdered(child, indent, idx)
				items = append(items, liContent)
				idx++
			}
		}
		return strings.Join(items, "\n")
	case "li":
		inner := c.convertChildren(n, indent, false)
		inner = strings.TrimSpace(inner)
		return inner
	case "blockquote":
		inner := c.convertChildren(n, indent, false)
		if strings.TrimSpace(inner) == "" {
			return ""
		}
		lines := strings.Split(strings.TrimRight(inner, "\n"), "\n")
		var sb strings.Builder
		for i, line := range lines {
			if line == "" {
				sb.WriteString(">")
			} else {
				sb.WriteString("> ")
				sb.WriteString(line)
			}
			if i < len(lines)-1 {
				sb.WriteString("\n")
			}
		}
		return sb.String()
	case "hr":
		return "* * *"
	case "br":
		return "\n"
	default:
		return c.convertChildren(n, indent, false)
	}
}

func (c *Converter) convertLi(node *html.Node, indent int) string {
	var parts []string
	var currentInline bytes.Buffer
	flushInline := func() {
		if currentInline.Len() > 0 {
			text := strings.TrimSpace(currentInline.String())
			if text != "" {
				parts = append(parts, text)
			}
			currentInline.Reset()
		}
	}
	for child := node.FirstChild; child != nil; child = child.NextSibling {
		if child.Type == html.TextNode {
			currentInline.WriteString(child.Data)
		} else if child.Type == html.ElementNode {
			tag := strings.ToLower(child.Data)
			if tag == "ul" || tag == "ol" {
				flushInline()
				nested := c.convertNode(child, indent+1, false)
				lines := strings.Split(nested, "\n")
				var indented []string
				indentStr := strings.Repeat(" ", 2*(indent+1))
				for _, line := range lines {
					if line == "" {
						indented = append(indented, indentStr)
					} else {
						indented = append(indented, indentStr+line)
					}
				}
				parts = append(parts, strings.Join(indented, "\n"))
			} else if tag == "p" {
				flushInline()
				pContent := c.convertNode(child, indent, false)
				pContent = strings.TrimSpace(pContent)
				if pContent != "" {
					parts = append(parts, pContent)
				}
			} else if tag == "br" {
				currentInline.WriteString("  \n")
			} else {
				inline := c.convertNode(child, indent, false)
				currentInline.WriteString(inline)
			}
		}
	}
	flushInline()
	if len(parts) == 0 {
		return "- "
	}
	first := parts[0]
	lines := strings.Split(first, "\n")
	var sb strings.Builder
	sb.WriteString("- ")
	sb.WriteString(lines[0])
	for _, l := range lines[1:] {
		sb.WriteString("\n")
		sb.WriteString(strings.Repeat(" ", 2))
		sb.WriteString(l)
	}
	for _, p := range parts[1:] {
		sb.WriteString("\n")
		sb.WriteString(strings.Repeat(" ", 2))
		sb.WriteString("\n")
		pLines := strings.Split(p, "\n")
		indentStr := strings.Repeat(" ", 2)
		for i, pl := range pLines {
			if i == 0 {
				sb.WriteString(indentStr)
				sb.WriteString(pl)
			} else {
				sb.WriteString("\n")
				sb.WriteString(indentStr)
				sb.WriteString(pl)
			}
		}
	}
	return sb.String()
}

func (c *Converter) convertLiOrdered(node *html.Node, indent int, index int) string {
	marker := fmt.Sprintf("%d. ", index)
	markerLen := len(marker)
	var parts []string
	var currentInline bytes.Buffer
	flushInline := func() {
		if currentInline.Len() > 0 {
			text := strings.TrimSpace(currentInline.String())
			if text != "" {
				parts = append(parts, text)
			}
			currentInline.Reset()
		}
	}
	for child := node.FirstChild; child != nil; child = child.NextSibling {
		if child.Type == html.TextNode {
			currentInline.WriteString(child.Data)
		} else if child.Type == html.ElementNode {
			tag := strings.ToLower(child.Data)
			if tag == "ul" || tag == "ol" {
				flushInline()
				nested := c.convertNode(child, indent+1, false)
				lines := strings.Split(nested, "\n")
				var indented []string
				indentStr := strings.Repeat(" ", (indent+1)*markerLen)
				for _, line := range lines {
					if line == "" {
						indented = append(indented, indentStr)
					} else {
						indented = append(indented, indentStr+line)
					}
				}
				parts = append(parts, strings.Join(indented, "\n"))
			} else if tag == "p" {
				flushInline()
				pContent := c.convertNode(child, indent, false)
				pContent = strings.TrimSpace(pContent)
				if pContent != "" {
					parts = append(parts, pContent)
				}
			} else if tag == "br" {
				currentInline.WriteString("  \n")
			} else {
				inline := c.convertNode(child, indent, false)
				currentInline.WriteString(inline)
			}
		}
	}
	flushInline()
	if len(parts) == 0 {
		return marker
	}
	first := parts[0]
	lines := strings.Split(first, "\n")
	var sb strings.Builder
	sb.WriteString(marker)
	sb.WriteString(lines[0])
	for _, l := range lines[1:] {
		sb.WriteString("\n")
		sb.WriteString(strings.Repeat(" ", markerLen))
		sb.WriteString(l)
	}
	for _, p := range parts[1:] {
		sb.WriteString("\n")
		sb.WriteString(strings.Repeat(" ", markerLen))
		sb.WriteString("\n")
		pLines := strings.Split(p, "\n")
		indentStr := strings.Repeat(" ", markerLen)
		for i, pl := range pLines {
			if i == 0 {
				sb.WriteString(indentStr)
				sb.WriteString(pl)
			} else {
				sb.WriteString("\n")
				sb.WriteString(indentStr)
				sb.WriteString(pl)
			}
		}
	}
	return sb.String()
}

func (c *Converter) convertChildren(n *html.Node, indent int, inTable bool) string {
	var sb strings.Builder
	var lastWasBr bool
	for child := n.FirstChild; child != nil; child = child.NextSibling {
		if child.Type == html.ElementNode && strings.ToLower(child.Data) == "br" {
			if !lastWasBr {
				count := 1
				next := child.NextSibling
				for next != nil {
					if next.Type == html.TextNode {
						if strings.TrimSpace(next.Data) == "" {
							next = next.NextSibling
							continue
						} else {
							break
						}
					}
					if next.Type == html.ElementNode && strings.ToLower(next.Data) == "br" {
						count++
						next = next.NextSibling
					} else {
						break
					}
				}
				if count == 1 {
					sb.WriteString("  \n")
				} else {
					sb.WriteString("\n\n")
				}
				lastWasBr = true
				skip := count - 1
				for skip > 0 && child.NextSibling != nil {
					next := child.NextSibling
					for next != nil && next.Type == html.TextNode && strings.TrimSpace(next.Data) == "" {
						next = next.NextSibling
					}
					if next != nil && next.Type == html.ElementNode && strings.ToLower(next.Data) == "br" {
						child = next
						skip--
					} else {
						break
					}
				}
			}
			continue
		}
		lastWasBr = false
		if child.Type == html.TextNode {
			txt := child.Data
			if n.Data == "pre" {
				sb.WriteString(txt)
			} else {
				if strings.TrimSpace(txt) == "" {
					continue
				}
				normalized := strings.ReplaceAll(txt, "\n", " ")
				normalized = strings.ReplaceAll(normalized, "\r", " ")
				normalized = strings.ReplaceAll(normalized, "\t", " ")
				normalized = regexp.MustCompile(`\s+`).ReplaceAllString(normalized, " ")
				escaped := escapeText(normalized)
				sb.WriteString(escaped)
			}
		} else if child.Type == html.ElementNode {
			inner := c.convertNode(child, indent, inTable)
			sb.WriteString(inner)
		}
	}
	return sb.String()
}

