func escapeLinkText(s string) string {
	var sb strings.Builder
	for _, ch := range s {
		switch ch {
		case '\\', '[', ']', '`', '*', '_':
			sb.WriteRune('\\')
			sb.WriteRune(ch)
		default:
			sb.WriteRune(ch)
		}
	}
	return sb.String()
}

func escapeImageAlt(s string) string {
	var sb strings.Builder
	for _, ch := range s {
		if ch == '\\' || ch == '[' || ch == ']' {
			sb.WriteRune('\\')
			sb.WriteRune(ch)
		} else {
			sb.WriteRune(ch)
		}
	}
	return sb.String()
}

func escapeInlineCode(s string) string {
	max := 0
	count := 0
	for _, ch := range s {
		if ch == '`' {
			count++
			if count > max {
				max = count
			}
		} else {
			count = 0
		}
	}
	fenceLen := max + 1
	if fenceLen < 1 {
		fenceLen = 1
	}
	fence := strings.Repeat("`", fenceLen)
	needsSpace := false
	if strings.HasPrefix(s, "`") || strings.HasPrefix(s, " ") || strings.HasSuffix(s, "`") || strings.HasSuffix(s, " ") {
		needsSpace = true
	}
	if needsSpace {
		return fence + " " + s + " " + fence
	}
	return fence + s + fence
}

func encodeLinkDestination(s string) string {
	var sb strings.Builder
	for _, ch := range s {
		switch ch {
		case ' ':
			sb.WriteString("%20")
		case '(':
			sb.WriteString("%28")
		case ')':
			sb.WriteString("%29")
		case '[':
			sb.WriteString("%5B")
		case ']':
			sb.WriteString("%5D")
		case '<':
			sb.WriteString("%3C")
		case '>':
			sb.WriteString("%3E")
		case '"':
			sb.WriteString("%22")
		case '`':
			sb.WriteString("%60")
		case '\'':
			sb.WriteString("%27")
		default:
			if ch < 32 || ch > 126 {
				sb.WriteString(url.PathEscape(string(ch)))
			} else {
				sb.WriteRune(ch)
			}
		}
	}
	return sb.String()
}

func resolveURL(base, ref string) string {
	if ref == "" {
		return base
	}
	baseURL, err := url.Parse(base)
	if err != nil {
		return ref
	}
	refURL, err := url.Parse(ref)
	if err != nil {
		return ref
	}
	resolved := baseURL.ResolveReference(refURL)
	return resolved.String()
}

func (c *Converter) convertTable(tableNode *html.Node) string {
	var rows [][]*html.Node
	var rowTypes [][]string
	var caption string
	var findCaption func(*html.Node)
	findCaption = func(n *html.Node) {
		if n.Type == html.ElementNode && strings.ToLower(n.Data) == "caption" {
			var sb strings.Builder
			for child := n.FirstChild; child != nil; child = child.NextSibling {
				sb.WriteString(c.convertNode(child, 0, true))
			}
			caption = strings.TrimSpace(sb.String())
			return
		}
		for child := n.FirstChild; child != nil; child = child.NextSibling {
			findCaption(child)
		}
	}
	findCaption(tableNode)

	var traverse func(*html.Node)
	traverse = func(n *html.Node) {
		if n.Type == html.ElementNode && strings.ToLower(n.Data) == "tr" {
			var cells []*html.Node
			var types []string
			for child := n.FirstChild; child != nil; child = child.NextSibling {
				if child.Type == html.ElementNode {
					tag := strings.ToLower(child.Data)
					if tag == "td" || tag == "th" {
						cells = append(cells, child)
						types = append(types, tag)
					}
				}
			}
			rows = append(rows, cells)
			rowTypes = append(rowTypes, types)
			return
		}
		for child := n.FirstChild; child != nil; child = child.NextSibling {
			traverse(child)
		}
	}
	traverse(tableNode)

	if len(rows) == 0 {
		if caption != "" {
			return caption + "\n"
		}
		return "\n"
	}

	type cellContent struct {
		text      string
		hasNewline bool
	}

	var tableData [][]cellContent
	for _, row := range rows {
		var rowData []cellContent
		for _, cell := range row {
			txt, hasNL := c.convertTableCell(cell)
			rowData = append(rowData, cellContent{text: txt, hasNewline: hasNL})
		}
		tableData = append(tableData, rowData)
	}

	if c.opts.NewlineBehavior == "skip" {
		for _, row := range tableData {
			for _, cell := range row {
				if cell.hasNewline {
					return c.fallbackTableRender(rows)
				}
			}
		}
	}

	grid := c.expandTableGrid(rows, rowTypes, tableData)

	if c.opts.SkipEmptyRows {
		var filtered [][]string
		for _, row := range grid {
			isEmpty := true
			for _, cell := range row {
				if strings.TrimSpace(cell) != "" {
					isEmpty = false
					break
				}
			}
			if !isEmpty {
				filtered = append(filtered, row)
			}
		}
		grid = filtered
	}

	if len(grid) == 0 {
		if caption != "" {
			return caption + "\n"
		}
		return "\n"
	}

	firstRowIsHeader := false
	if len(rowTypes) > 0 {
		for _, t := range rowTypes[0] {
			if t == "th" {
				firstRowIsHeader = true
				break
			}
		}
	}
	hasHeader := firstRowIsHeader || c.opts.HeaderPromotion

	var headerRow []string
	var dataRows [][]string
	if hasHeader {
		headerRow = grid[0]
		if len(grid) > 1 {
			dataRows = grid[1:]
		}
	} else {
		if len(grid) > 0 {
			numCols := len(grid[0])
			headerRow = make([]string, numCols)
			dataRows = grid
		}
	}

	numCols := len(headerRow)
	for _, r := range dataRows {
		if len(r) > numCols {
			numCols = len(r)
		}
	}
	if len(headerRow) < numCols {
		for i := len(headerRow); i < numCols; i++ {
			headerRow = append(headerRow, "")
		}
	}
	for i := range dataRows {
		if len(dataRows[i]) < numCols {
			for j := len(dataRows[i]); j < numCols; j++ {
				dataRows[i] = append(dataRows[i], "")
			}
		}
	}

	maxLens := make([]int, numCols)
	if c.opts.CellPadding == "aligned" {
		for col := 0; col < numCols; col++ {
			max := 0
			if len(headerRow[col]) > max {
				max = len(headerRow[col])
			}
			for _, row := range dataRows {
				if len(row[col]) > max {
					max = len(row[col])
				}
			}
			maxLens[col] = max
		}
	}

	var out strings.Builder
	switch c.opts.CellPadding {
	case "none":
		out.WriteString("|")
		for col := 0; col < numCols; col++ {
			out.WriteString(headerRow[col])
			out.WriteString("|")
		}
		out.WriteString("\n")
		out.WriteString("|")
		for col := 0; col < numCols; col++ {
			out.WriteString("---")
			out.WriteString("|")
		}
		out.WriteString("\n")
		for _, row := range dataRows {
			out.WriteString("|")
			for col := 0; col < numCols; col++ {
				out.WriteString(row[col])
				out.WriteString("|")
			}
			out.WriteString("\n")
		}
	case "minimal":
		out.WriteString("|")
		for col := 0; col < numCols; col++ {
			out.WriteString(" ")
			out.WriteString(headerRow[col])
			out.WriteString(" |")
		}
		out.WriteString("\n")
		out.WriteString("|")
		for col := 0; col < numCols; col++ {
			out.WriteString("---")
			out.WriteString("|")
		}
		out.WriteString("\n")
		for _, row := range dataRows {
			out.WriteString("|")
			for col := 0; col < numCols; col++ {
				out.WriteString(" ")
				out.WriteString(row[col])
				out.WriteString(" |")
			}
			out.WriteString("\n")
		}
	default:
		out.WriteString("|")
		for col := 0; col < numCols; col++ {
			content := headerRow[col]
			padded := content + strings.Repeat(" ", maxLens[col]-len(content))
			out.WriteString(" ")
			out.WriteString(padded)
			out.WriteString(" |")
		}
		out.WriteString("\n")
		out.WriteString("|")
		for col := 0; col < numCols; col++ {
			dashes := strings.Repeat("-", maxLens[col]+2)
			if len(dashes) < 3 {
				dashes = "---"
			}
			out.WriteString(dashes)
			out.WriteString("|")
		}
		out.WriteString("\n")
		for _, row := range dataRows {
			out.WriteString("|")
			for col := 0; col < numCols; col++ {
				content := row[col]
				padded := content + strings.Repeat(" ", maxLens[col]-len(content))
				out.WriteString(" ")
				out.WriteString(padded)
				out.WriteString(" |")
			}
			out.WriteString("\n")
		}
	}
	if caption != "" {
		out.WriteString("\n")
		out.WriteString(caption)
		out.WriteString("\n")
	}
	return out.String()
}

func (c *Converter) convertTableCell(cell *html.Node) (string, bool) {
	var hasNewline bool
	var checkBr func(*html.Node) bool
	checkBr = func(n *html.Node) bool {
		if n.Type == html.ElementNode && strings.ToLower(n.Data) == "br" {
			return true
		}
		for child := n.FirstChild; child != nil; child = child.NextSibling {
			if checkBr(child) {
				return true
			}
		}
		return false
	}
	if checkBr(cell) {
		hasNewline = true
	}
	var countBlocks int
	var checkBlocks func(*html.Node)
	checkBlocks = func(n *html.Node) {
		if n.Type == html.ElementNode {
			tag := strings.ToLower(n.Data)
			if tag == "p" || tag == "div" || tag == "ul" || tag == "ol" || tag == "blockquote" || tag == "pre" || tag == "h1" || tag == "h2" || tag == "h3" || tag == "h4" || tag == "h5" || tag == "h6" || tag == "table" {
				countBlocks++
			}
		}
		for child := n.FirstChild; child != nil; child = child.NextSibling {
			checkBlocks(child)
		}
	}
	checkBlocks(cell)
	if countBlocks > 1 {
		hasNewline = true
	}
	if countBlocks == 1 {
		var singleBlockTag string
		var findSingle func(*html.Node)
		findSingle = func(n *html.Node) {
			if singleBlockTag != "" {
				return
			}
			if n.Type == html.ElementNode {
				tag := strings.ToLower(n.Data)
				if tag == "ul" || tag == "ol" || tag == "div" || tag == "blockquote" || tag == "pre" || tag == "table" {
					singleBlockTag = tag
					return
				}
			}
			for child := n.FirstChild; child != nil; child = child.NextSibling {
				findSingle(child)
			}
		}
		findSingle(cell)
		if singleBlockTag == "ul" || singleBlockTag == "ol" {
			hasNewline = true
		}
	}
	if c.opts.NewlineBehavior == "preserve" && hasNewline {
		var parts []string
		for child := cell.FirstChild; child != nil; child = child.NextSibling {
			if child.Type == html.TextNode {
				if strings.TrimSpace(child.Data) != "" {
					parts = append(parts, strings.TrimSpace(child.Data))
				}
			} else if child.Type == html.ElementNode {
				tag := strings.ToLower(child.Data)
				if tag == "br" {
					parts = append(parts, "<br />")
				} else if tag == "p" {
					inner := c.convertChildren(child, 0, true)
					inner = strings.TrimSpace(inner)
					parts = append(parts, inner)
				} else {
					inner := c.convertNode(child, 0, true)
					inner = strings.TrimSpace(inner)
					if inner != "" {
						parts = append(parts, inner)
					}
				}
			}
		}
		var sb strings.Builder
		for i, p := range parts {
			if i > 0 {
				if p == "<br />" {
					sb.WriteString("  <br />")
				} else {
					if sb.Len() > 0 {
						sb.WriteString("<br /><br /><br /><br />")
					}
					sb.WriteString(p)
				}
			} else {
				if p == "<br />" {
					sb.WriteString("  <br />")
				} else {
					sb.WriteString(p)
				}
			}
		}
		return sb.String(), false
	}
	inner := c.convertChildren(cell, 0, true)
	inner = strings.TrimSpace(inner)
	inner = strings.ReplaceAll(inner, "\n", " ")
	inner = regexp.MustCompile(`\s+`).ReplaceAllString(inner, " ")
	inner = strings.TrimSpace(inner)
	return inner, hasNewline
}

func (c *Converter) expandTableGrid(rows [][]*html.Node, rowTypes [][]string, tableData [][]struct {
	text       string
	hasNewline bool
}) [][]string {
	type cellInfo struct {
		content string
		colspan int
		rowspan int
	}
	var raw [][]cellInfo
	for i, row := range rows {
		var r []cellInfo
		for j, cell := range row {
			colspan := 1
			rowspan := 1
			if cs := getAttr(cell, "colspan"); cs != "" {
				if v, err := strconv.Atoi(cs); err == nil && v > 1 {
					colspan = v
				}
			}
			if rs := getAttr(cell, "rowspan"); rs != "" {
				if v, err := strconv.Atoi(rs); err == nil && v > 1 {
					rowspan = v
				}
			}
			content := ""
			if i < len(tableData) && j < len(tableData[i]) {
				content = tableData[i][j].text
			}
			r = append(r, cellInfo{content: content, colspan: colspan, rowspan: rowspan})
		}
		raw = append(raw, r)
	}
	maxCols := 0
	for _, row := range raw {
		sum := 0
		for _, cell := range row {
			sum += cell.colspan
		}
		if sum > maxCols {
			maxCols = sum
		}
	}
	// pending rowspans
	type pending struct {
		remaining int
		content   string
	}
	pendingSpans := make([]pending, maxCols)
	var grid [][]string
	for _, row := range raw {
		var curRow []string
		colIdx := 0
		cellIdx := 0
		for colIdx < maxCols {
			if colIdx < len(pendingSpans) && pendingSpans[colIdx].remaining > 0 {
				content := pendingSpans[colIdx].content
				if c.opts.SpanBehavior == "empty" {
					content = ""
				}
				curRow = append(curRow, content)
				pendingSpans[colIdx].remaining--
				colIdx++
				continue
			}
			if cellIdx < len(row) {
				cell := row[cellIdx]
				curRow = append(curRow, cell.content)
				// handle colspan
				for k := 1; k < cell.colspan; k++ {
					var extra string
					if c.opts.SpanBehavior == "mirror" {
						extra = cell.content
					} else {
						extra = ""
					}
					curRow = append(curRow, extra)
					colIdx++
				}
				// handle rowspan for future rows
				if cell.rowspan > 1 {
					for k := 0; k < cell.colspan; k++ {
						idx := colIdx - cell.colspan + k + 1
						if idx < 0 {
							idx = colIdx
						}
						// Actually need to set pending for each column covered
						// For simplicity, set pending for the columns
						// The colspan already advanced colIdx, so we need to set pending for those cols
						// Let's set after
					}
					// For each col covered by this cell, set pending rowspan
					for k := 0; k < cell.colspan; k++ {
						pendingCol := len(curRow) - cell.colspan + k
						if pendingCol >= 0 && pendingCol < maxCols {
							pendingSpans[pendingCol] = pending{remaining: cell.rowspan - 1, content: cell.content}
						}
					}
				}
				cellIdx++
				colIdx++
			} else {
				curRow = append(curRow, "")
				colIdx++
			}
		}
		grid = append(grid, curRow)
	}
	return grid
}

func (c *Converter) fallbackTableRender(rows [][]*html.Node) string {
	var rowTexts []string
	for _, row := range rows {
		var sb strings.Builder
		for _, cell := range row {
			inner := c.convertChildren(cell, 0, true)
			inner = strings.TrimSpace(inner)
			sb.WriteString(inner)
		}
		rowTexts = append(rowTexts, sb.String())
	}
	result := strings.Join(rowTexts, "\n\n")
