            res+="%5B"
        elif ch=="]":
            res+="%5D"
        elif ch=="<":
            res+="%3C"
        elif ch==">":
            res+="%3E"
        elif ch=='"':
            res+="%22"
        elif ch=="`":
            res+="%60"
        elif ch=="'":
            res+="%27"
        else:
            if ord(ch)<32 or ord(ch)>126:
                from urllib.parse import quote
                res+=quote(ch)
            else:
                res+=ch
    return res

def resolve_url(base, ref):
    if ref=="":
        return base
    return urljoin(base, ref)

# Converter class
class Converter:
    def __init__(self, opts):
        self.opts=opts

    def convert_children(self, node):
        res=""
        last_was_br=False
        i=0
        while i<len(node.children):
            child=node.children[i]
            if not child.is_text and child.tag=="br":
                # Count consecutive br
                count=1
                j=i+1
                while j<len(node.children):
                    nxt=node.children[j]
                    if nxt.is_text and nxt.text.strip()=="":
                        j+=1
                        continue
                    if not nxt.is_text and nxt.tag=="br":
                        count+=1
                        j+=1
                    else:
                        break
                if count==1:
                    res+="  \n"
                else:
                    res+="\n\n"
                last_was_br=True
                # Skip counted brs
                skip=count-1
                while skip>0 and i+1<len(node.children):
                    nxt=node.children[i+1]
                    if nxt.is_text and nxt.text.strip()=="":
                        i+=1
                        continue
                    if not nxt.is_text and nxt.tag=="br":
                        i+=1
                        skip-=1
                    else:
                        break
                i+=1
                continue
            last_was_br=False
            if child.is_text:
                txt=child.text
                if node.tag=="pre":
                    res+=txt
                else:
                    if txt.strip()=="":
                        i+=1
                        continue
                    # Normalize whitespace
                    normalized=txt.replace("\n"," ").replace("\r"," ").replace("\t"," ")
                    normalized=re.sub(r'\s+', ' ', normalized)
                    escaped=escape_text(normalized)
                    res+=escaped
            else:
                inner=self.convert_node(child)
                res+=inner
            i+=1
        return res

    def convert_node(self, node, indent=0):
        if node.is_text:
            return node.text
        tag=node.tag
        if tag in ("script","style","head","title","meta","link"):
            return ""
        if not self.opts.get("table_plugin"):
            if tag in ("table","tr","td","th","tbody","thead","tfoot","colgroup","col","caption"):
                res=""
                for child in node.children:
                    res+=self.convert_node(child, indent)
                return res
        else:
            if tag=="table":
                role=node.attrs.get("role","")
                if role=="presentation" and not self.opts.get("presentation_tables"):
                    res=""
                    for child in node.children:
                        res+=self.convert_node(child, indent)
                    return res
                return self.convert_table(node)

        if tag in ("h1","h2","h3","h4","h5","h6"):
            level=int(tag[1])
            inner=self.convert_children(node)
            inner=inner.strip()
            if inner=="":
                return ""
            return "#"*level+" "+inner
        if tag=="p":
            inner=self.convert_children(node)
            inner=inner.strip()
            if inner=="":
                return ""
            return inner
        if tag in ("strong","b"):
            inner=self.convert_children(node)
            if inner.strip()=="":
                return ""
            delim=self.opts.get("strong_delimiter","**")
            return delim+inner+delim
        if tag in ("em","i"):
            inner=self.convert_children(node)
            if inner.strip()=="":
                return ""
            return "*"+inner+"*"
        if tag in ("s","del","strike"):
            inner=self.convert_children(node)
            if inner.strip()=="":
                return ""
            if self.opts.get("strikethrough"):
                return "~~"+inner+"~~"
            return inner
        if tag=="code":
            if node.parent and node.parent.tag=="pre":
                res=""
                for child in node.children:
                    if child.is_text:
                        res+=child.text
                    else:
                        res+=self.convert_node(child, indent)
                return res
            inner=""
            for child in node.children:
                if child.is_text:
                    inner+=child.text
                else:
                    inner+=self.convert_node(child, indent)
            return escape_inline_code(inner)
        if tag=="pre":
            code_content=""
            lang=""
            for child in node.children:
                if not child.is_text and child.tag=="code":
                    class_attr=child.attrs.get("class","")
                    parts=class_attr.split()
                    for p in parts:
                        if p.startswith("language-"):
                            lang=p[len("language-"):]
                            break
                        if p.startswith("lang-"):
                            lang=p[len("lang-"):]
                            break
                    res=""
                    for gc in child.children:
                        if gc.is_text:
                            res+=gc.text
                        else:
                            res+=self.convert_node(gc, indent)
                    code_content=res
                    break
            if code_content=="":
                res=""
                for child in node.children:
                    if child.is_text:
                        res+=child.text
                    else:
                        res+=self.convert_node(child, indent)
                code_content=res
            fence="```"
            max_ticks=0
            count=0
            for ch in code_content:
                if ch=="`":
                    count+=1
                    if count>max_ticks:
                        max_ticks=count
                else:
                    count=0
            if max_ticks>=3:
                fence="`"*(max_ticks+1)
            if lang:
                fence+=lang
            # Build
            out=fence+"\n"+code_content
            if not code_content.endswith("\n"):
                out+="\n"
            closing="```"
            if max_ticks>=3:
                closing="`"*(max_ticks+1)
            out+=closing
            return out
        if tag=="a":
            href=node.attrs.get("href","")
            title=node.attrs.get("title","")
            inner=self.convert_children(node)
            resolved=href
            domain=self.opts.get("domain","")
            if domain:
                resolved=resolve_url(domain, href)
            encoded=encode_link_destination(resolved)
            escaped_text=escape_link_text(inner)
            if title:
                if '"' in title and "'" not in title:
                    title_part=f"'{title}'"
                elif "'" in title and '"' not in title:
                    title_part=f'"{title}"'
                elif '"' in title and "'" in title:
                    escaped_title=title.replace('"','\\"')
                    title_part=f'"{escaped_title}"'
                else:
                    title_part=f'"{title}"'
                return f"[{escaped_text}]({encoded} {title_part})"
            else:
                return f"[{escaped_text}]({encoded})"
        if tag=="img":
            src=node.attrs.get("src","")
            alt=node.attrs.get("alt","")
            title=node.attrs.get("title","")
            domain=self.opts.get("domain","")
            resolved=src
            if domain:
                resolved=resolve_url(domain, src)
            encoded=encode_link_destination(resolved)
            escaped_alt=escape_image_alt(alt)
            if title:
                if '"' in title and "'" not in title:
                    title_part=f"'{title}'"
                elif "'" in title and '"' not in title:
                    title_part=f'"{title}"'
                elif '"' in title and "'" in title:
                    escaped_title=title.replace('"','\\"')
                    title_part=f'"{escaped_title}"'
                else:
                    title_part=f'"{title}"'
                return f"![{escaped_alt}]({encoded} {title_part})"
            else:
                return f"![{escaped_alt}]({encoded})"
        if tag=="ul":
            items=[]
            for child in node.children:
                if not child.is_text and child.tag=="li":
                    items.append(self.convert_li(child, indent))
            return "\n".join(items)
        if tag=="ol":
            start=1
            start_attr=node.attrs.get("start","")
            if start_attr:
                try:
                    start=int(start_attr)
                except:
                    start=1
            items=[]
            idx=start
            for child in node.children:
                if not child.is_text and child.tag=="li":
                    items.append(self.convert_li_ordered(child, indent, idx))
                    idx+=1
            return "\n".join(items)
        if tag=="li":
            inner=self.convert_children(node)
            return inner.strip()
        if tag=="blockquote":
            blocks=[]
            for child in node.children:
                md=self.convert_node(child, indent)
                trimmed=md.strip()
                if trimmed!="":
                    blocks.append(trimmed)
            inner="\n\n".join(blocks)
            if inner.strip()=="":
                return ""
            lines=inner.rstrip("\n").split("\n")
            out_lines=[]
            for line in lines:
                if line.strip()=="":
                    out_lines.append("> ")
                else:
                    out_lines.append("> "+line)
            return "\n".join(out_lines)
        if tag=="hr":
            return "* * *"
        if tag=="br":
            return "\n"
        # default
        return self.convert_children(node)

    def convert_li(self, node, indent):
        parts=[]
        current_inline=""
        def flush():
            nonlocal current_inline
            if current_inline.strip()!="":
                parts.append(current_inline.strip())
                current_inline=""
        for child in node.children:
            if child.is_text:
                current_inline+=child.text
            else:
                t=child.tag
                if t in ("ul","ol"):
                    flush()
                    nested=self.convert_node(child, indent+1)
                    parts.append(nested)
                elif t=="p":
                    flush()
                    p_content=self.convert_node(child, indent)
                    p_content=p_content.strip()
                    if p_content!="":
                        parts.append(p_content)
                elif t=="br":
                    current_inline+="  \n"
                else:
                    current_inline+=self.convert_node(child, indent)
        flush()
        if not parts:
            return "- "
        first=parts[0]
        lines=first.split("\n")
        out="- "+lines[0]
        for l in lines[1:]:
            out+="\n  "+l
        for p in parts[1:]:
            out+="\n  \n"
            plines=p.split("\n")
            for i, pl in enumerate(plines):
                if i==0:
                    out+="  "+pl
                else:
                    out+="\n  "+pl
        return out

    def convert_li_ordered(self, node, indent, index):
        marker=f"{index}. "
        marker_len=len(marker)
        parts=[]
        current_inline=""
        def flush():
            nonlocal current_inline
            if current_inline.strip()!="":
                parts.append(current_inline.strip())
                current_inline=""
        for child in node.children:
            if child.is_text:
                current_inline+=child.text
            else:
                t=child.tag
                if t in ("ul","ol"):
                    flush()
                    nested=self.convert_node(child, indent+1)
                    parts.append(nested)
                elif t=="p":
                    flush()
                    p_content=self.convert_node(child, indent)
                    p_content=p_content.strip()
                    if p_content!="":
                        parts.append(p_content)
                elif t=="br":
                    current_inline+="  \n"
                else:
                    current_inline+=self.convert_node(child, indent)
        flush()
        if not parts:
            return marker
        first=parts[0]
        lines=first.split("\n")
        out=marker+lines[0]
        for l in lines[1:]:
            out+="\n"+" "*marker_len+l
        for p in parts[1:]:
            out+="\n"+" "*marker_len+"\n"
            plines=p.split("\n")
            for i, pl in enumerate(plines):
                if i==0:
                    out+=" "*marker_len+pl
                else:
                    out+="\n"+" "*marker_len+pl
        return out

    def convert_table(self, table_node):
        # Find caption
        caption=""
        def find_caption(n):
            nonlocal caption
            if not n.is_text and n.tag=="caption":
                res=""
                for child in n.children:
                    res+=self.convert_node(child, 0)
                caption=res.strip()
                return
            for child in n.children:
                find_caption(child)
        find_caption(table_node)

        # Collect rows
        rows=[]
        row_types=[]
        def traverse(n):
            if not n.is_text and n.tag=="tr":
                cells=[]
                types=[]
                for child in n.children:
