        if not grid:
            if caption:
                return caption+"\n"
            return "\n"

        # Header promotion
        first_is_header=False
        if row_types:
            for t in row_types[0]:
                if t=="th":
                    first_is_header=True
                    break
        has_header=first_is_header or self.opts.get("header_promotion")

